private typealias E = EvidenceSeed

/// Alternate tellings, batch S: the same cases, played out another way.
extension StoryVariants {
    static let variantsS: [CaseTemplate] = [officeLaptopRaidV1, libraryReadingRoomV1, mopedFleeV1, nightNurseV1, twentiesCounterfeitV1, campTableBurnV1, courthouseKnifeV1, revokedToWorkV1, fakeCopV1, nursingDiplomaFakeV1, gymLockerWalletV1, campusThreatV1, golfCartDeathV1, youthRefereeV1, scriptPadPrintV1, weddingGiftBoxV1, neighborDogShotV1, crossingGuardCrashV1, knifeFightV1, washedChecksV1, kayakDockTheftV1, fairgroundRiotV1, unmarkedCarV1, driveByV1, fireAuxTreasurerV1, clothingBinTheftV1, smallClaimsLieV1, pickupLineDWIV1, massageTableV1, lotInvestmentFraudV1, petSuppliesBagV1, phoneKnockedAwayV1, oldMillRoadV1, unsecuredGunV1, videoThreatExtortionV1, laundromatChangeBoxV1, patioShoutingV1, restraintDeathV1]

    static let officeLaptopRaidV1 = SmallCases.make(
        key: "story.officeLaptopRaid",
        category: .property,
        headlines: ["Medical Billing Office Pried Open Over the Weekend", "Tracking Software Pings Stolen Laptops to Apartment Complex"],
        law: "feloniousBE",
        threshold: 6,
        spec: "Broke and entered a building of {V}, a medical billing company, with intent to commit larceny therein, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Nine laptops worth $11,000 were gone when staff opened {V}'s billing office on Monday. A rear window had been pried from a loading dock overnight on {DATE}. Tracking software on one laptop checked in from an apartment complex where {D} lives, and a parking-lot camera caught a hatchback like {D}'s. {DL} says a neighbor sold {D.him} one laptop in the hallway and that {D.he} knows nothing about the break-in.",
        state: [E(.digital, 3, "Tracker Check-In", "A laptop's recovery software reports its location from the apartment complex where {D} lives, twice in two days."), E(.video, 2, "Lot Camera", "A hatchback parks by the loading dock at 1:50 a.m. and leaves at 2:20 a.m. The plate is unreadable."), E(.document, 2, "Vehicle Registration", "{D} is the registered owner of a hatchback matching the color and a dented rear bumper.")],
        defense: [E(.statement, 2, "Hallway Sale", "{DL} says a neighbor sold {D.him} a used laptop for $80 and gave no name."), E(.document, 1, "Many Units", "The tracker's location covers a building with forty units.")],
        role: "Office manager",
        exam: [.direct("What did you find on Monday morning?", "\"A pried rear window at the loading dock and empty desks. Nine laptops, worth about $11,000, were gone.\""), .direct("How were the laptops traced?", "\"One had recovery software that reported its location twice in two days, from an apartment complex where {D} lives.\""), .direct("Does the software name a person?", "\"No. Only a building. It tells us an address, not who is holding the laptop.\""), .direct("What did the lot camera show?", "\"A hatchback parking by the loading dock at 1:50 a.m. and leaving at 2:20 a.m. We cannot read the plate.\""), .direct("What does the registration show?", "\"{DL} is the registered owner of a hatchback matching the one on the camera.\""), .direct("What was the effect on your office?", "\"We could not bill for days. Patient files were on those laptops, and we had to notify our clients.\""), .cross("Is the camera plate readable?", "\"It is not. The camera shows a hatchback and nothing that identifies it.\""), .cross("Is a hatchback like {D}'s common?", "\"Very. Many people drive them, and I would not say this one is rare.\""), .cross("Did the defendant ever work at your building?", "\"Not that I know. I do not recognize {DL}.\""), .cross("Did you recover the tracked laptop?", "\"Deputies did, from an apartment. I was not there.\""), .cross("Did the defendant cooperate?", "\"Yes. {DL} said a neighbor sold {DL} a laptop in the hallway, and {DL} gave deputies the device.\"")],
        defenseRole: "Neighbor in the complex",
        defenseExam: [.direct("Where do you live?", "\"In the same apartment complex as {D}. We share a hallway on the second floor.\""), .direct("Did you see a laptop sold in the hall?", "\"I heard people haggling one night. It was late, and I looked through the peephole.\""), .direct("Did you see who was selling?", "\"Only a hooded figure. I could not see a face.\""), .direct("Did you see {D}?", "\"I saw {DF} in the hall. {DF} was carrying a bag and talking with the person.\""), .direct("How long did the haggling last?", "\"A few minutes. Then I heard a door close, and it was quiet.\""), .direct("What did you think?", "\"That someone was selling a laptop cheap. I did not think it was a crime.\""), .cross("Did you see money exchanged?", "\"No. I only heard voices. I did not see any hands.\""), .cross("Did you see the laptop?", "\"Not clearly. I saw a bag, and I assumed.\""), .cross("Do you know the hooded person?", "\"No. I never saw that person before or since.\""), .cross("What night was it?", "\"A night that week. I cannot pin down the exact date.\""), .cross("Are you friends with the defendant?", "\"We say hello. I would not call us friends.\"")],
        theory: ("{D} pried a window, took laptops, and kept one at home.", "A used laptop bought in a hallway and a building full of neighbors."),
        allocution: "\"I should have asked where it came from. I am sorry.\"",
        truths: ("{DL} had once cleaned the building as a temp worker and knew the layout of the loading dock.", "A neighbor already on probation for burglary lives two doors down and was seen carrying boxes that night."),
        defendant: [.direct("Were you at the billing office?", "\"No. I was at home that night. I never went near the loading dock.\""), .direct("How did you get the laptop?", "\"A neighbor sold it to me for cheap. We agreed on a price in the hallway, and I paid cash.\""), .direct("Why did you not ask where it came from?", "\"It never crossed my mind to ask. It looked like a used laptop, and the price seemed reasonable.\""), .direct("Is that your hatchback?", "\"Yes, and a lot of people park near that dock. It is a busy area, and the camera does not show my plate.\""), .direct("What did you do when deputies came?", "\"I handed over the laptop and told them how I got it. I did not hide anything.\""), .direct("What do you want {V} to know?", "\"I am sorry for the loss. I bought a laptop in good faith, and I did not take yours.\""), .cross("The tracker found a laptop in your complex, didn't it?", "\"Yes. It was the one I bought from the neighbor.\""), .cross("You own a hatchback, don't you?", "\"Yes. It is like thousands of others.\""), .cross("You paid cash for a laptop in a hallway, didn't you?", "\"Yes. I thought it was a good deal.\""), .cross("You cannot name the neighbor, can you?", "\"I know the neighbor by sight. I do not have a name.\""), .cross("The laptop reported from your building twice, didn't it?", "\"Yes. I kept it on a table. I did not know it reported anywhere.\"")],
        openings: ("Nine laptops worth $11,000 were gone from {V}'s billing office after a rear window was pried at the loading dock. Tracking software on one laptop checked in from the apartment complex where {D} lives, and a hatchback like {D}'s was on the lot camera.", "A neighbor sold {D} one laptop in the hallway, and {D} was home that night. Buying a cheap laptop is not the same as breaking in to steal nine."),
        closings: ("A tracker that reports from {D}'s building, a hatchback at the dock at 1:50, and a registration that matches. The laptops led straight to {D}'s door.", "A hallway sale, a common hatchback, and a plate no camera could read. The State must prove {D} was at that dock."),
        timeline: [(0, "1:50 a.m.: a hatchback parks at the dock."), (0, "2:20 a.m.: the hatchback leaves."), (1, "Monday morning: staff find the window pried and nine laptops missing."), (2, "The tracker reports an apartment complex.")],
        identified: "Recovery software and a parking-lot camera.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction)

    static let libraryReadingRoomV1 = SmallCases.make(
        key: "story.libraryReadingRoom",
        category: .publicOrder,
        headlines: ["Speakerphone Argument Clears Quiet Study Room", "Library Staff Call Deputy After Cursing Fit"],
        law: "disorderly",
        spec: "Disturbed the peace by loud and abusive language in a public library, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "On {DATE}, {D} took a call on speakerphone in the quiet study room of a public library and began yelling about a car repair bill. When a clerk asked {D.him} to step outside, {D.he} cursed at the clerk. Four students packed up and left. A deputy arrived and {D} finally went out. {DL} says {D.he} did not realize how loud the call was.",
        state: [E(.statement, 3, "Clerk Report", "{D} used a profanity-filled voice at the clerk after being asked to leave the room."), E(.video, 2, "Study Room Camera", "{D} paces with a phone held out and four students leave.")],
        defense: [E(.statement, 1, "Hearing Trouble", "{DL} says {D.he} wears a hearing aid and the battery had died.")],
        role: "Library clerk",
        exam: [.direct("What did {D} do in the study room?", "\"Yelled into a phone on speaker in a silent room. It was the quiet study room, where people come to concentrate.\""), .direct("What was the yelling about?", "\"A car repair bill. {D} shouted about the cost and the work, and the voice carried across the room.\""), .direct("How did the defendant respond when you asked?", "\"With curse words, loudly, in front of the students. {D.He} was very angry.\""), .direct("What did the students do?", "\"Four of them packed up and left. They looked upset, and one said it was too loud to study.\""), .direct("What does the study room camera show?", "\"It shows {DL} pacing with a phone held out, and four students leaving.\""), .direct("How did it end?", "\"A deputy arrived and {DL} finally went out. It took a few minutes of talking.\""), .cross("Did the defendant threaten you?", "\"No. {D.He} cursed, but did not threaten me.\""), .cross("Could the defendant have missed your first request?", "\"Possibly, at first. I spoke quietly, and {D.he} was on a loud call.\""), .cross("Did the defendant calm down eventually?", "\"Yes. Once outside, {D.he} apologized, though I was still shaken.\""), .cross("Was {D} using a phone on speaker?", "\"Yes. It was held out in front of {DL}, and the caller was audible.\""), .cross("Has the defendant been in the library before?", "\"Yes. {DL} has a card. I have seen {DL} before.\"")],
        theory: ("{D} turned a quiet room into a shouting match.", "A person who could not hear how loud {D.he} was."),
        allocution: "\"I am sorry for the scene I made.\"",
        truths: ("{DL} had been asked to lower {D.his} voice at the same library three times that month.", "A clinic receipt shows {DL} had an audiology visit that morning and left with a dead hearing aid battery."),
        defendant: [.direct("Were you loud?", "\"I could not tell. I was on speaker, and I was upset, and I did not realize how far it carried.\""), .direct("Why did you curse?", "\"I was already upset about the bill. I was angry at the repair shop, and it spilled over onto the clerk.\""), .direct("Were you asked to leave?", "\"I did not hear it until the deputy came. I was focused on the call, and I did not process what the clerk said.\""), .direct("Who was on the phone?", "\"The repair shop. They quoted me a high price, and I was arguing with them.\""), .direct("How did you feel afterward?", "\"Embarrassed. I did not mean to disturb anyone, and I felt bad when I saw the students leave.\""), .direct("What do you want the library to know?", "\"I am sorry. I did not realize how loud I was, and I will take calls outside from now on.\""), .cross("The study room is a quiet room, isn't it?", "\"Yes. I know that now. I did not think when I answered the call.\""), .cross("You cursed at the clerk, didn't you?", "\"Yes. I did, and I truly am sorry.\""), .cross("Four students left because of you, didn't they?", "\"So the clerk says. I am sorry for that.\""), .cross("A deputy had to come, didn't one?", "\"Yes. I finally heard when the deputy spoke.\""), .cross("You held the phone out on speaker, didn't you?", "\"Yes. I did not think about the others in the room.\"")],
        openings: ("{D} took a call on speakerphone in the quiet study room of a public library and began yelling about a car repair bill. When a clerk asked {D} to step outside, {D} cursed at the clerk, four students left, and a deputy had to come.", "{D} did not realize how loud the call was and did not hear the first request. A loud phone call is rude, not a crime."),
        closings: ("A quiet study room, a speakerphone, a clerk cursed at, four students gone, and a deputy called. {D} knew where {D} was.", "A call about a bill, a first request {D} did not hear, and an apology afterward. The State must prove {D} meant to disturb the library."),
        timeline: [(0, "2 p.m.: the call starts in the study room."), (0, "2:10 p.m.: the clerk asks {D} to leave."), (0, "2:20 p.m.: a deputy arrives.")],
        identified: "A library clerk and a study room camera.",
        mood: .indifferent)

    static let mopedFleeV1 = SmallCases.make(
        key: "story.mopedFlee",
        category: .traffic,
        headlines: ["Moped Rider Weaves Through Cemetery to Dodge Patrol Car", "Scraped Moped Found Behind Rider's Apartment"],
        law: "fleeing",
        threshold: 6,
        spec: "Operated a motor vehicle on a street while fleeing from a law enforcement officer who was attempting to stop the vehicle, on {DATE}.",
        ages: 18...40,
        victim: false,
        summary: "At 10:15 p.m. on {DATE}, a deputy lit up a moped with no headlight in a steady rain. The rider turned into a cemetery, wove between headstones, and came out on a side street. The deputy lost the moped but picked up a broken mirror on the grass. Two days later a tipster led deputies to a moped with a scraped fender behind {D}'s apartment. {DL} says {D.he} thought a car was tailgating {D.him} and never saw it was a patrol car.",
        state: [E(.video, 3, "Body Camera", "Lights and siren behind a moped; the rider glances back twice and turns into the cemetery gate."), E(.physical, 2, "Broken Mirror", "A mirror that fits the mount on the moped behind {D}'s apartment.", .search), E(.document, 2, "Registration", "The moped is registered to {D}.")],
        defense: [E(.statement, 2, "Thought It Was a Tailgater", "{DL} says the rain and a fogged visor hid the lights and {D.he} sped up to get away from a car crowding {D.him}."), E(.document, 1, "Weather Report", "Heavy rain that night.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did you see that night?", "\"A moped with no headlight and the rider hunched forward, at 10:15 p.m. in a steady rain.\""), .direct("What did the rider do when you lit up?", "\"Turned into the cemetery and kept going between the stones. The rider glanced back twice before the gate.\""), .direct("Could you see the rider's face?", "\"No. Only a dark visor and a hooded jacket. The rain made everything harder to see.\""), .direct("Was it raining?", "\"Hard. Visibility was poor, and the road was slick.\""), .direct("What did you recover?", "\"A broken mirror on the grass near the cemetery gate. It looked like it had snapped off a moped.\""), .direct("How did you find {D}?", "\"Two days later a tipster led us to a moped with a scraped fender behind {D}'s apartment. The mirror fit its mount.\""), .cross("Did you lose the moped?", "\"Yes. It came out on a side street, and I lost sight of it in the rain.\""), .cross("Is the moped registered to the defendant?", "\"Yes. The registration is in {D.his} name.\""), .cross("Did you see the defendant?", "\"No. I did not see the rider's face, and I cannot say it was {DL}.\""), .cross("Could the mirror have broken some other way?", "\"Yes. A mirror can snap in many ways, and I did not see it break.\""), .cross("Did the defendant cooperate?", "\"Yes. {D.He} said a car was behind {D.him} and that {D.he} did not see blue lights until too late.\"")],
        theory: ("{D} saw the lights, fled through a cemetery, and hid the moped.", "A rider in the rain who thought a car was too close."),
        allocution: "\"I should have pulled over. I am sorry.\"",
        truths: ("A friend of {DL}'s told a deputy that {DL} said, \"I ditched the cop in the graveyard.\"", "The helmet visor in {DL}'s apartment was fogged through and a dashboard view shows the rain hid any lights."),
        defendant: [.direct("Were you in the cemetery?", "\"Yes. I cut through to get away from headlights. A car was right behind me, and I was scared.\""), .direct("Did you see blue lights?", "\"Not until too late. The rain and the glare hid them, and I was looking at the road.\""), .direct("You looked back twice, didn't you?", "\"A car was right behind me. I looked to see how close it was, and I did not know it was a deputy.\""), .direct("Why was there no headlight?", "\"It was out. I was riding home, and I did not have time to fix it.\""), .direct("Why hide the moped?", "\"I did not hide it. It was parked behind my apartment, where I always park it.\""), .direct("What do you want the deputy to know?", "\"I did not know you were behind me. I would have stopped if I had seen the lights.\""), .cross("You turned into a cemetery, didn't you?", "\"Yes. It was a shortcut, and I wanted to get off the road.\""), .cross("You rode between headstones in the rain, didn't you?", "\"Yes. It was reckless, and I know it.\""), .cross("Your moped has a scraped fender, doesn't it?", "\"Yes. I scraped it earlier on a curb.\""), .cross("A mirror matching your moped was found, wasn't it?", "\"So the deputy says. It could have come off in the cemetery.\""), .cross("You did not stop for the deputy, did you?", "\"I did not know it was a deputy. I did not see the lights.\"")],
        openings: ("A deputy lit up a moped with no headlight in a steady rain. The rider turned into a cemetery, wove between headstones, and escaped, leaving a broken mirror that fits the moped behind {D}'s apartment.", "{D} thought a car was following and never saw blue lights in the rain. A rider who is frightened by headlights is not fleeing the law."),
        closings: ("A moped with no headlight, a rider who glanced back twice, a cemetery run, and a mirror that fits {D}'s moped. {D} ran from the deputy.", "Heavy rain, glare, a car behind, and no clear view of any lights. The State must prove {D} knew a deputy was behind and chose to run."),
        timeline: [(0, "10:15 p.m.: the deputy lights up the moped."), (0, "10:17 p.m.: the rider turns through the cemetery."), (0, "10:20 p.m.: the moped disappears; a mirror lies on the grass."), (2, "A tip points to {D}'s apartment.")],
        identified: "A broken mirror and a tip.",
        mood: .indifferent,
        genders: ["D": .male])

    static let nightNurseV1 = SmallCases.make(
        key: "story.nightNurse",
        category: .violent,
        headlines: ["Nurse Accused of Poisoning Patients With Potassium", "Heart Unit Deaths Trace to Missing Potassium Vials"],
        law: "murder1",
        threshold: 9,
        spec: "With premeditation and deliberation, killed {V}, a patient at a regional hospital, by injecting concentrated potassium chloride.",
        ages: 30...48,
        victim: true,
        summary: "In the spring, three heart patients on the intensive care unit went into cardiac arrest between 3 and 4 a.m. in a stretch of six weeks. Blood from the last one, {V}, showed extreme potassium and no kidney problem to explain it. A pharmacist found that concentrated potassium vials had been pulled for rooms where none was ordered. {D}, a night nurse, was on duty every time. {DL} says the pharmacy count is sloppy, that other nurses cover each other's rooms, and that {D.he} gave only ordered medicine.",
        state: [E(.forensic, 3, "Potassium Level", "{V}'s blood potassium was far above any natural level, with normal kidney function."), E(.document, 3, "Dispensing Log", "Seven vials pulled on {DL}'s login for rooms with no potassium order."), E(.document, 2, "Shift Records", "{DL} worked all three arrest nights; no other nurse worked more than one."), E(.digital, 2, "Door Log", "{DL}'s badge entered the medication room within ten minutes before each event.")],
        defense: [E(.document, 2, "Shared Logins", "Staff routinely left a workstation logged in for others to use."), E(.document, 2, "Staff Shortage", "The unit ran two nurses short on each of the nights."), E(.forensic, 1, "Sample Handling", "One sample was drawn after a long delay.")],
        role: "Toxicologist",
        exam: [.direct("What did the blood show?", "\"A potassium level that would stop a heart. Kidneys were fine, so something was injected from outside.\""), .direct("Could disease cause it?", "\"Not at this level without major kidney failure. {V} had normal kidney function.\""), .direct("Can you say whose hand gave it?", "\"No. Only that it came from outside. Toxicology cannot name a person.\""), .direct("What did the dispensing log show?", "\"Seven vials of concentrated potassium pulled on {D}'s login for rooms with no potassium order.\""), .direct("What did the shift records show?", "\"{D.He} worked all three arrest nights. No other nurse worked more than one.\""), .direct("What is the pattern of the arrests?", "\"Three heart patients went into cardiac arrest between 3 and 4 a.m. over six weeks, and {V} was the last.\""), .cross("Did one sample wait for hours?", "\"Yes. A delay can only change the number slightly. It does not explain a lethal level.\""), .cross("Could the potassium have been ordered?", "\"Not for {V}. No order existed for the rooms where vials were pulled.\""), .cross("Did others share the login?", "\"On busy nights, I understand people used whatever screen was open. That was reported to me.\""), .cross("Did you examine other patients?", "\"Only {V} and the two earlier arrests, by records. I could not test those.\""), .cross("Did {D} cooperate?", "\"Yes. {D.He} gave a statement and denied giving potassium.\"")],
        defenseRole: "Charge nurse",
        defenseExam: [.direct("What is your role?", "\"I am a charge nurse. I supervise the unit, assign nurses, and help with every kind of emergency.\""), .direct("How did the logins work?", "\"On a busy night, whoever was closest used whatever screen was open. Many of us never logged out.\""), .direct("What kind of nurse is {D}?", "\"Careful and kind. Families asked for {D.him}, and patients felt safe.\""), .direct("Did you pull potassium on the defendant's login?", "\"Never. I would not do that, and I have no memory of anyone doing it.\""), .direct("Do you know who did?", "\"I cannot name anyone. I only know our logins were loose.\""), .direct("What was the unit like those nights?", "\"Understaffed, hectic, and loud. We did what we could.\""), .cross("Did the defendant work every arrest night?", "\"Yes. {D.He} worked many nights, and the arrests happened at night.\""), .cross("Did you see the defendant in the med room?", "\"Many times a shift. Every nurse is in and out.\""), .cross("Could the defendant have pulled the vials?", "\"I cannot say that {D.he} did not. I know what I saw, and I never saw it.\""), .cross("Did you raise concerns about the logins?", "\"Yes. I told the manager that people should log out, and nothing changed.\""), .cross("Are you friends with {D}?", "\"We are colleagues. I respect {D.his} work.\"")],
        theory: ("{D} was there every time, pulled the potassium, and killed patients.", "A hospital with shared logins and too few nurses is blaming one person."),
        allocution: "\"I became a nurse to help people. I would never hurt one.\"",
        truths: ("A used syringe with {DL}'s fingerprint was found in a locked room only {DL} entered that night.", "After {DL} was suspended, another patient had a potassium arrest on a night {DL} was not at work."),
        defendant: [.direct("Did you give any patient potassium?", "\"Only what was ordered. I gave exactly what the order said, and I never gave extra.\""), .direct("Were you in the medication room?", "\"Many times a shift. That is where all the medications are, and every nurse goes in and out.\""), .direct("Seven pulls on your login, weren't there?", "\"I do not know who used it. I never pulled potassium for rooms without an order.\""), .direct("Did you leave your login open?", "\"Everyone did. The screens were busy, and we did not always log out.\""), .direct("How did you feel about the arrests?", "\"Heartbroken. I cared for those patients, and I could not understand what had happened.\""), .direct("What do you want {V}'s family to know?", "\"I am so sorry. I would never hurt a patient, and I want to know who did.\""), .cross("You worked all three arrest nights, didn't you?", "\"Yes. I work many nights. That is how I was scheduled.\""), .cross("No other nurse worked more than one of them, did they?", "\"So the records say. I cannot explain it.\""), .cross("Concentrated potassium is dangerous, isn't it?", "\"Very. It must be handled carefully, and I never mishandled it.\""), .cross("Seven vials were pulled on your login, weren't they?", "\"So I am told. I did not pull them.\""), .cross("You are the common thread, aren't you?", "\"I am a night nurse on a busy unit. That does not make me a killer.\"")],
        openings: ("In six weeks, three heart patients on the intensive care unit went into cardiac arrest between 3 and 4 a.m. {V}'s blood showed extreme potassium with normal kidneys, seven vials were pulled on {D}'s login for rooms with no order, and {D} worked all three nights.", "Logins on that unit were shared and screens were left open. {D} was a careful night nurse, and nothing shows {D}'s hand gave potassium."),
        closings: ("Extreme potassium, seven vials pulled on {D}'s login for rooms with no order, and one nurse on duty for all three arrests. A pattern like that is no coincidence.", "Open screens, shared logins, and a toxicology result that cannot name a hand. The State must prove {D} gave the potassium, and no one saw it."),
        timeline: [(-42, "First unexplained arrest on the unit."), (-21, "Second arrest at 3 a.m."), (0, "3:40 a.m.: {V} arrests and dies."), (10, "The pharmacist reports missing potassium vials.")],
        identified: "A pharmacy audit of potassium vials and staffing records.",
        aggravating: ["The victim was particularly vulnerable", "The defendant took advantage of a position of trust", "The offense involved multiple victims"],
        mitigating: ["No prior criminal record"],
        mood: .wantsConviction,
        impact: "{V} came in for a valve repair and was supposed to go home that weekend.",
        doctrines: ["burdenOfProof", "expertTestimony"])

    static let twentiesCounterfeitV1 = SmallCases.make(
        key: "story.twentiesCounterfeit",
        category: .whiteCollar,
        headlines: ["Fake Fifties Show Up at Roadside Produce Stands", "Bank Deposit Pen Flags Counterfeit Bills"],
        law: "uttering",
        threshold: 7,
        spec: "Uttered counterfeit currency to {V} and others, totaling $1,500, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Over one Saturday, {DATE}, six roadside produce stands and a flea market booth each took a fifty-dollar bill that later failed a bank's detection pen. All thirty bills had the same serial number. {V}, a stand owner, wrote down the plate of a truck. It is registered to {D}. {DL} says {D.he} was paid in cash for a used trailer and did not know the bills were fake.",
        state: [E(.physical, 3, "Thirty Fifties", "Thirty bills with an identical serial number and faint printer lines."), E(.video, 3, "Stand Camera and Plate", "{V}'s camera shows {D} paying with a fifty and the truck's plate."), E(.digital, 2, "Marketplace Ad", "Two days earlier {DL} posted a trailer for sale and later took the listing down.")],
        defense: [E(.statement, 1, "Trailer Sale", "{DL} says a buyer paid in cash for the trailer.")],
        role: "Produce stand owner",
        exam: [.direct("What did {D} buy at your stand?", "\"A bag of peaches, paid with a fifty. {D} was pleasant, and we chatted about the weather.\""), .direct("When did you find out the bill was fake?", "\"The bank pen turned the bill black at the deposit window. I was shocked, because I had no reason to doubt it.\""), .direct("Did the defendant act nervous?", "\"No, friendly. {DL} smiled, took the bag, and walked away like any customer.\""), .direct("Did the defendant get change?", "\"Yes, thirty-some dollars. I counted it out of my cash box.\""), .direct("What did you do after the bank pen?", "\"I wrote down the plate of the truck from my camera and called the sheriff. I knew other stands might have the same bill.\""), .direct("How many bills were involved?", "\"Thirty fifties with the same serial number, passed at six stands and a flea market booth in one day.\""), .cross("Did the defendant hide the plate?", "\"No. The truck sat plainly in front of my stand with the plate in view.\""), .cross("Did you check the bill when you took it?", "\"I held it up to the light. It looked normal.\""), .cross("Did the defendant spend only fifties?", "\"I saw one. Other stands saw others, and I do not know all of them.\""), .cross("Did {D} say where the money came from?", "\"No. We did not talk about that.\""), .cross("Did you see the defendant at the other stands?", "\"No. I only know what the camera and the sheriff told me.\"")],
        defenseRole: "Friend who helped load the trailer",
        defenseExam: [.direct("How do you know {D}?", "\"I am a friend. I helped {D} load a used trailer when it was sold.\""), .direct("Did you see the sale?", "\"A buyer came with an envelope of cash. We shook hands and loaded the trailer.\""), .direct("Did you see the bills?", "\"Only the envelope. I did not see the bills inside, and I did not count them.\""), .direct("What did the buyer look like?", "\"Average build, ball cap, and a pickup. I did not catch a name.\""), .direct("Did the defendant count the cash?", "\"Quickly, with the envelope flap open. {D.He} did not look closely.\""), .direct("What did the defendant do with the cash?", "\"Put it in a jacket and went out for errands. {D.He} seemed happy about the sale.\""), .cross("Did you see the serial numbers?", "\"No. I did not see a single bill.\""), .cross("Did you know the buyer?", "\"No. {D.He} said it was a stranger from an online ad.\""), .cross("Did you see where the cash went?", "\"No. I left after the trailer was loaded.\""), .cross("Do you know the buyer's name?", "\"No. I never got one.\""), .cross("Are you friends with the defendant?", "\"Yes. I am telling you what I saw, and I would say the same of anyone.\"")],
        theory: ("{D} spent counterfeit fifties across the county.", "A cash buyer paid {D} with bills {D.he} never inspected."),
        allocution: "\"I am sorry for passing them. I should have checked.\"",
        truths: ("A color printer and a stack of cut paper were in {DL}'s garage.", "The trailer buyer left a deposit slip and a license plate with a friend of {DL}'s that was never followed up."),
        defendant: [.direct("Did you print any bills?", "\"No. I never printed a bill, and I do not own the equipment to do it.\""), .direct("Where did you get them?", "\"The buyer of my trailer. The buyer paid in cash from an envelope, and I took it at face value.\""), .direct("Why spend them all in one day?", "\"I had errands. I needed gas, groceries, and supplies, and I had a lot of fifties.\""), .direct("Why take the ad down?", "\"Because it sold. I removed the listing the day I got the cash.\""), .direct("How did you feel when you learned?", "\"Sick. I had spent thirty fake bills without knowing, and I was embarrassed.\""), .direct("What do you want the stand owners to know?", "\"I am so sorry. I would never knowingly pass a fake bill, and I will help pay them back.\""), .cross("You paid with a fifty at {V}'s stand, didn't you?", "\"Yes. I paid for peaches with a fifty, and I did not know it was fake.\""), .cross("Thirty bills with the same serial number came from you, didn't they?", "\"So the bank says. I did not look at serial numbers.\""), .cross("You cannot name the buyer, can you?", "\"No. I never got a name or a license.\""), .cross("You posted the trailer two days earlier, didn't you?", "\"Yes. It sold quickly.\""), .cross("You spent fifties at seven places in a day, didn't you?", "\"Yes. I had a lot of errands.\"")],
        openings: ("Over one Saturday, six roadside produce stands and a flea market booth each took a fifty-dollar bill that later failed a bank's detection pen. All thirty bills carried the same serial number, and {V}, a stand owner, wrote down a plate registered to {D}.", "{D} was paid in cash for a used trailer and spent it, not knowing the bills were fake. A seller who spends what a buyer handed over is a victim of the same scheme."),
        closings: ("Thirty fifties with one serial number, a truck and a plate caught on {V}'s camera, and a trailer ad taken down. {D} spent the counterfeits.", "A trailer sold for cash, an envelope no one counted, and a buyer no one can find. The State must prove {D} knew the bills were fake."),
        timeline: [(-2, "{DL} posts a trailer for sale."), (-1, "The trailer is sold, {D.he} says."), (0, "Morning to afternoon: the fifties are spent."), (1, "The bank flags the bills.")],
        identified: "A stand camera and a truck plate.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["mistakeOfFact"],
        genders: ["D": .male])

    static let campTableBurnV1 = SmallCases.make(
        key: "story.campTableBurn",
        category: .property,
        headlines: ["Trailhead Kiosk Burned at County Campground", "Trail Camera Catches Late-Night Fire"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured the real property of {V}, a county campground, causing damage of $1,900, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A wooden information kiosk and its roof at a county campground burned at 2 a.m. on {DATE}, causing $1,900 in damage. A wildlife trail camera caught someone near the kiosk before the fire and the gate log shows {D}'s truck entering at midnight. {DL} says {D.he} was burning scrap pallets in a ground pit and the wind carried embers.",
        state: [E(.video, 3, "Trail Camera", "Two photos show a person pouring from a jug beside the kiosk at 1:45 a.m."), E(.document, 2, "Gate Log", "{D}'s truck is logged in at midnight and out at 2:30 a.m.")],
        defense: [E(.statement, 1, "Pallet Fire", "{DL} says an ember jumped from a pallet fire.")],
        role: "Park ranger",
        exam: [.direct("What was damaged?", "\"The whole kiosk and its roof. A wooden information kiosk at the county campground burned at 2 a.m.\""), .direct("What did the camera show?", "\"A person with a jug at the foot of the kiosk at 1:45 a.m. Two photos show the person pouring.\""), .direct("Could you see a face?", "\"Not clearly. The photos are dark and the person is turned away.\""), .direct("What does the gate log show?", "\"{D}'s truck logged in at midnight and out at 2:30 a.m. The gate is the only way in.\""), .direct("What was the damage?", "\"$1,900 in repairs. We rebuilt the kiosk and replaced the map and signs.\""), .direct("Was there wind?", "\"A light breeze. Not strong, but enough to move embers around the campground.\""), .cross("Did you see {D} at the kiosk?", "\"No. I was off-duty. I know only what the camera and the gate log show.\""), .cross("Is the jug in the photo identifiable?", "\"It looks like a gas jug. I cannot tell what it held.\""), .cross("Could the fire have started from a campfire?", "\"It could. A fire in a ground pit can throw embers if the wind picks up.\""), .cross("Were there other campers?", "\"A few. We interviewed them, and none saw the fire start.\""), .cross("Did the defendant cooperate?", "\"Yes. {D.He} said {D.he} was burning scrap pallets in a pit and walked by the kiosk to read the map.\"")],
        theory: ("{D} soaked a kiosk with fuel and lit it.", "Stray embers from a pallet fire."),
        allocution: "\"I was careless. I am sorry.\"",
        truths: ("A scorched gas jug that matched the trail camera photo was in the bed of {DL}'s truck.", "The pit fire was forty feet from the kiosk behind a gravel berm and the first flames began on the kiosk's far side."),
        defendant: [.direct("Did you burn it?", "\"No. I did not set the kiosk on fire, and I did not pour anything on it.\""), .direct("What was in the jug?", "\"Fuel for my camp stove. I carry a small jug when I camp, and I had it that night.\""), .direct("You were at the kiosk, weren't you?", "\"I walked by to read the map. I wanted to see the trail layout, and I stood there a few minutes.\""), .direct("Why were you burning pallets?", "\"I was burning scrap pallets in a ground pit to stay warm. I kept it small.\""), .direct("You left at 2:30, didn't you?", "\"I saw the fire and left. I was scared I would be blamed.\""), .direct("What do you want the park to know?", "\"I am sorry the kiosk burned. I did not do it, and I should have stayed and helped.\""), .cross("You entered the campground at midnight, didn't you?", "\"Yes. I had a late arrival, and the gate was open.\""), .cross("A person with a jug was at the kiosk at 1:45, wasn't there?", "\"So the camera says. I had a jug, and I was near the kiosk.\""), .cross("You left after the fire started, didn't you?", "\"Yes. I should have stayed.\""), .cross("A pit fire can throw embers, can't it?", "\"Yes. That is why I think the wind carried embers. I kept it small.\""), .cross("You never reported the fire, did you?", "\"No. I panicked, and I am so sorry.\"")],
        openings: ("A wooden information kiosk at a county campground burned at 2 a.m., causing $1,900 in damage. A trail camera caught a person pouring from a jug beside it at 1:45, and the gate log shows {D}'s truck entering at midnight.", "{D} was burning scrap pallets in a ground pit and walked by the kiosk to read the map. A breeze carried the embers, and {D}'s jug held fuel for a camp stove."),
        closings: ("A person with a jug at 1:45, a truck logged in at midnight and out at 2:30, and a kiosk in ashes. The camera and the gate log both point to {D}.", "A camp stove jug, a pit fire, and a breeze that moves embers. The State must prove {D} poured fuel on the kiosk."),
        timeline: [(0, "Midnight: {D}'s truck enters the gate."), (0, "1:45 a.m.: the trail camera photos."), (0, "2 a.m.: the kiosk burns."), (0, "2:30 a.m.: the truck leaves.")],
        identified: "A trail camera and the gate log.",
        mitigating: ["The defendant has accepted responsibility"],
        mood: .indifferent)

    static let courthouseKnifeV1 = SmallCases.make(
        key: "story.courthouseKnife",
        category: .publicOrder,
        headlines: ["Wand Finds Pocketknife Sewn Into Coat Lining", "Courthouse Visitor Says the Coat Was Not Hers"],
        law: "concealedWeapon",
        spec: "Carried a concealed knife on or about {D.his} person into a courthouse, on {DATE}.",
        ages: 20...65,
        victim: false,
        summary: "On {DATE}, {D} came to the courthouse to pay a fine and passed the first scanner without a beep. At a second wand check, officers found a locking pocketknife tucked in an inner coat pocket. {DL} says the coat was a thrift-store purchase and the knife came with it.",
        state: [E(.physical, 3, "Pocketknife", "A locking pocketknife with a three-inch blade in an inner coat pocket.", .search), E(.statement, 2, "Wand Officer", "The wand beeped on the coat's left side and {D} said, \"It is only a little one.\"")],
        defense: [E(.document, 1, "Thrift Receipt", "A receipt shows the coat was bought nine days earlier.")],
        role: "Courthouse deputy",
        exam: [.direct("Where was the knife?", "\"Inner pocket, left side, of {D}'s coat. It was a locking pocketknife with a three-inch blade.\""), .direct("How did {D} pass the first scanner?", "\"It did not beep. The first scanner missed it, and {D.he} went through without a sound.\""), .direct("How was it found?", "\"At a second wand check. The wand beeped on the left side of the coat, and officers checked the inner pocket.\""), .direct("What did the defendant say?", "\"That it was a little one. {D.He} said, 'It is only a little one,' when the wand beeped.\""), .direct("Was the defendant cooperative?", "\"Yes. {D.He} stood still, raised arms, and handed over the knife when asked.\""), .direct("Why are knives barred from the courthouse?", "\"Courts are places of high emotion. We screen everyone who comes in to keep judges, staff, and the public safe.\""), .cross("Did the defendant try to hide it?", "\"No. {D.He} did not run or resist, and told us right away about the knife.\""), .cross("Did the first scanner miss it often?", "\"Sometimes. Small metal in a coat lining can slip past if it is angled.\""), .cross("Did the defendant threaten anyone?", "\"No. {D.He} came to pay a fine and was polite throughout.\""), .cross("Did {D} say how the knife got there?", "\"{D.He} said the coat was a thrift-store purchase and the knife came with it.\""), .cross("Was the knife open?", "\"No. It was closed and locked, in an inner pocket.\"")],
        theory: ("{D} walked into court with a knife on {D.him}.", "A coat from a thrift store came with a knife nobody checked."),
        allocution: "\"I should have checked the pockets.\"",
        truths: ("{DL} told the deputy that {D.he} carried it for protection on the bus.", "The thrift store's donation tag on the coat still showed a prior owner's name and the knife had a different owner's initials."),
        defendant: [.direct("Did you know it was there?", "\"No. I did not know the knife was in the coat until the wand beeped and the deputy found it.\""), .direct("What did you say to the deputy?", "\"I said it was just a little one once I saw it. I was embarrassed and surprised.\""), .direct("When did you buy the coat?", "\"Nine days ago, at a thrift store. It was cheap, and I liked it.\""), .direct("You never checked the pockets?", "\"Not all of them. I checked the outer ones, and I did not look in the lining.\""), .direct("Why did you come to the courthouse?", "\"To pay a fine. I wanted to take care of it and go home.\""), .direct("What do you want the court to know?", "\"I truly am sorry. I did not bring the knife on purpose, and I should have checked the coat.\""), .cross("The knife was in your coat, wasn't it?", "\"Yes. In an inner pocket. I did not know.\""), .cross("You said 'it is only a little one,' didn't you?", "\"Yes. I said it after I saw it, and it came out wrong.\""), .cross("A locking knife is not a toy, is it?", "\"No. I know that. I did not buy the coat for a knife.\""), .cross("You walked through the first scanner without a beep, didn't you?", "\"Yes. I did not know it would beep.\""), .cross("You bought the coat yourself, didn't you?", "\"Yes. I paid a few dollars. The knife came with it.\"")],
        openings: ("{D} came to the courthouse to pay a fine and passed the first scanner without a beep. At a second wand check, officers found a locking pocketknife with a three-inch blade tucked in an inner coat pocket.", "The coat was a thrift-store purchase nine days earlier, and the knife came with it. {D} did not know it was there and said so as soon as it was found."),
        closings: ("A three-inch locking knife in an inner pocket, a first scanner that missed it, and a wand beep on the left side. {D} walked into a courthouse armed.", "A thrift-store coat, a lining {D} never searched, and a knife found at the first question. The State must prove {D} knew it was there."),
        timeline: [(-9, "{DL} buys the coat."), (0, "9:10 a.m.: {DL} passes the first scanner."), (0, "9:14 a.m.: the wand beeps and the knife is found.")],
        identified: "A courthouse deputy with a wand.",
        mood: .indifferent,
        genders: ["D": .male])

    static let revokedToWorkV1 = SmallCases.make(
        key: "story.revokedToWork",
        category: .traffic,
        headlines: ["Checkpoint Stop Finds Revoked License on Daycare Run", "Driver Says Clerk Error Kept Revocation Alive"],
        law: "dwlr",
        threshold: 5,
        spec: "Drove a motor vehicle on a public highway while {D.his} driver's license was revoked, on {DATE}.",
        ages: 25...58,
        victim: false,
        summary: "A trooper checking licenses at a roadblock at 6:50 a.m. on {DATE} ran {D}'s license and found a revocation from over a year earlier for a missed court date. {D} was taking a child to daycare before a 7:30 shift. {DL} says the fine was paid months before the stop and the court clerk never cleared the revocation.",
        state: [E(.document, 3, "DMV Record", "A revocation entered a year earlier for failure to appear in court."), E(.video, 2, "Checkpoint Video", "{D} hands over a card and the trooper reads the record aloud at the window.")],
        defense: [E(.document, 2, "Paid Receipt", "A clerk's receipt shows the court fine was paid and the case closed ten weeks before the stop.")],
        role: "State Highway Patrol trooper",
