        ages: 30...55,
        victim: true,
        summary: "At 9:40 p.m. on {DATE}, someone in a dark vest marked \"POLICE\" and a badge on a chain knocked on {V}'s apartment door and said there had been a noise complaint and a warrant check. {V} kept the chain on, asked for a case number, and was told to \"just open up.\" {V} called 911 and the visitor left. A doorbell camera caught a face and a hatchback. {D}, a private security guard, owns a matching hatchback. {DL} says {D.he} was checking an alarm call at a nearby unit and wears a company vest.",
        state: [E(.video, 3, "Doorbell Video", "A figure in a vest marked POLICE and a chain badge at the door, face partly visible under a cap."), E(.physical, 2, "Vest and Badge", "A vest with a removable POLICE panel and a gold badge in {DL}'s hatchback.", .search), E(.statement, 2, "Photo Lineup", "{V} picked {DL}'s photo: \"That is the face on the porch. I am fairly sure.\"")],
        defense: [E(.document, 2, "Company Letter", "{DL}'s employer says the vest says SECURITY and the POLICE panel was never issued."), E(.statement, 1, "Alarm Call", "{DL} says {D.he} checked an alarm at the next building that night.")],
        role: "Detective",
        exam: [.direct("What did {V} tell you?", "\"A visitor in a police vest said there was a noise complaint and a warrant check and demanded entry.\""), .direct("What did {V} do?", "\"Kept the chain on, asked for a case number, and was told to 'just open up.' Then {V} called 911 and the visitor left.\""), .direct("What did the doorbell camera show?", "\"A figure in a vest marked POLICE and a chain badge at the door, face partly visible under a cap.\""), .direct("What did you find in {D}'s car?", "\"A vest with a loose police panel and a gold badge. They were in a hatchback that matches the one on the camera.\""), .direct("Does the vest say police?", "\"The panel does. It is a removable panel, attached with hook and loop.\""), .direct("Did {V} identify anyone?", "\"{V} picked {D}'s photo from a lineup and said, 'That is the face on the porch. I am fairly sure.'\""), .cross("Did anyone verify the alarm call?", "\"No. I did not. I did not check the company's log, and I wish I had.\""), .cross("Is the defendant a private security officer?", "\"Yes. {DL} works for a security company and wears a uniform with a badge that says Special Officer.\""), .cross("Could the vest be part of a security uniform?", "\"A vest could be. A police panel is not part of a security uniform.\""), .cross("Was {V} sure about the face?", "\"Fairly sure. {V} was not certain, and said so.\""), .cross("Did the defendant deny it?", "\"Yes. {D.He} said {D.he} was at an alarm call next door.\"")],
        defenseRole: "Supervisor at {DL}'s security company",
        defenseExam: [.direct("What is your role?", "\"I supervise officers at the security company that employs {D}. I schedule patrols and review reports.\""), .direct("Was {D} on duty that night?", "\"On patrol, near that complex. {D.He} was assigned to a route that included the area.\""), .direct("Did the company issue a police panel?", "\"Never. Our vests say Security. Nothing we issue says Police.\""), .direct("What does the defendant's badge say?", "\"Special Officer. It is a company badge that identifies {DF} as a security officer.\""), .direct("Was there an alarm call that night?", "\"Yes. An alarm call came in at the building next door, and {D.he} was dispatched to it.\""), .direct("What kind of employee is the defendant?", "\"Reliable. {DF} has worked for us for years and has never been accused of impersonating anyone.\""), .cross("Did you see the defendant at the alarm?", "\"No. I was in the office. I know from the log.\""), .cross("Could the defendant have left the alarm site?", "\"I cannot say. I do not track every minute.\""), .cross("Did {D} ever wear a vest that said Police?", "\"I never saw it. I cannot say what is in {D.his} car.\""), .cross("Why would a vest have a removable panel?", "\"I do not know. Ours are plain.\""), .cross("Are you friendly with the defendant?", "\"I supervise {DF}. I would say the same about anyone I supervise.\"")],
        theory: ("{D} posed as an officer to get into a home.", "A guard on patrol, a company vest, and an unsure photo pick."),
        allocution: "\"I never meant to scare anyone. I am sorry.\"",
        truths: ("{DL}'s phone sat near the apartment building at 9:40 p.m. with no alarm call on the company's log.", "The company's log shows an alarm call at the adjoining building at 9:35 p.m. that {DL} answered."),
        defendant: [.direct("Why do you have a vest?", "\"It is part of my security uniform. I wear it on patrol, and I keep a spare in the car.\""), .direct("Where were you at 9:40?", "\"At an alarm call next door. I was dispatched, I checked the building, and I logged it.\""), .direct("The vest says POLICE, doesn't it?", "\"I never put that panel on. It came with the vest I bought online, and I left it loose.\""), .direct("Why the badge?", "\"It says Special Officer. It is for work, and I wear it on my uniform.\""), .direct("Did you knock on {V}'s door?", "\"No. I have never been to that apartment, and I did not impersonate a police officer.\""), .direct("What do you want {V} to know?", "\"I am sorry you were frightened. It was not me, and I hope you find the person.\""), .cross("A vest with a police panel and a gold badge were in your car, weren't they?", "\"Yes. The panel was loose, and the badge is my work badge.\""), .cross("{V} picked your photo, didn't {V.he}?", "\"Fairly sure, not certain. I was not there.\""), .cross("Your hatchback matches the one on the doorbell camera, doesn't it?", "\"It looks like many hatchbacks. I drive one.\""), .cross("You cannot prove you were at the alarm call at 9:40, can you?", "\"The company's log can. I answered an alarm call.\""), .cross("You own a vest with a police panel, don't you?", "\"I own a vest with a panel I did not attach. I should not have kept it.\"")],
        openings: ("At 9:40 p.m., someone in a dark vest marked POLICE and a badge on a chain knocked on {V}'s apartment door, claimed a warrant check, and told {V} to 'just open up.' A doorbell camera caught a face and a hatchback, and a vest and gold badge were found in {D}'s car.", "{D} was at an alarm call next door, and a security vest is not a police vest. A fairly sure lineup pick is not proof."),
        closings: ("A visitor in a police vest, a face on a doorbell camera, a vest and gold badge in {D}'s hatchback, and {V}'s lineup pick. The porch and the car match.", "A security officer at an alarm call, a loose panel never attached, and a lineup pick that was only fairly sure. The State must prove {D} knocked on that door."),
