        identified: "A doorbell camera and a photo lineup.",
        aggravating: ["The offense targeted a person alone at night"],
        mitigating: ["No prior criminal record", "The defendant has been gainfully employed"],
        mood: .wantsConviction,
        impact: "I do not open the door for anyone now without calling first.",
        genders: ["D": .male, "V": .female])

    static let nursingDiplomaFakeV1 = SmallCases.make(
        key: "story.nursingDiplomaFake",
        category: .whiteCollar,
        headlines: ["Clinic Hires Nurse Using Emailed Diploma", "Credential Audit Finds Nursing School Never Heard of Applicant"],
        law: "uttering",
        threshold: 7,
        spec: "Uttered a forged diploma to {V}, a medical clinic, with intent to defraud, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} emailed a nursing diploma and a licensing form to a medical clinic on {DATE} and was hired as a floor nurse. A year-end credential audit found the state board had no license under that number, and the nursing school had no student by that name. File data on the diploma PDF showed it was made on {D}'s home computer. {DL} says a placement company handled the paperwork.",
        state: [E(.digital, 3, "Diploma File", "Metadata shows the PDF was created on a computer registered to {D}, with the school's logo pasted in."), E(.document, 3, "Board Letter", "The state board says no license exists under the number provided."), E(.document, 2, "School Letter", "The school says no student by that name ever enrolled.")],
        defense: [E(.statement, 1, "Placement Company", "{DL} says a placement company prepared and sent the forms."), E(.document, 1, "Invoice", "An invoice from the placement company for $400.")],
        role: "Clinic administrator",
        exam: [.direct("What did you receive from {D}?", "\"A diploma PDF and a license form, emailed to the clinic on the date in question, and {D} was hired as a floor nurse.\""), .direct("How did you learn there was a problem?", "\"A year-end credential audit found the state board had no license under that number.\""), .direct("What did the board say?", "\"No license under that number. The board has no record of a nurse by that license number.\""), .direct("What did the school say?", "\"That no student by that name ever enrolled. The nursing school checked its records and found nothing.\""), .direct("What did the file data on the diploma show?", "\"The PDF was created on a computer registered to {D.him}, with the school's logo pasted in.\""), .direct("What does the defendant do at the clinic?", "\"Floor nurse duties, including patient care. {D.He} worked there for about a year.\""), .cross("Did any patient complain?", "\"No complaints. {D.He} was well liked, and patients said nice things.\""), .cross("Did the defendant use the clinic computer?", "\"The documents came from a home email. The clinic computer was not used for the application.\""), .cross("Did the defendant perform well?", "\"By every measure I had. {D.He} was punctual and competent.\""), .cross("Did you check the license before hiring?", "\"I checked the form. I did not call the board, and I wish I had.\""), .cross("Did the defendant explain?", "\"Yes. {D.He} said a placement company handled the paperwork.\"")],
        defenseRole: "Former coworker",
        defenseExam: [.direct("How do you know {D}?", "\"We worked together at the clinic for a year, and I saw {D} on nearly every shift we shared.\""), .direct("Did the defendant mention a placement company?", "\"Said {D.he} paid someone to handle it. {D.He} told me the company did all of the paperwork for the job.\""), .direct("Did you ever see that company?", "\"No. I never saw an invoice, an email, or a name from them, and I never met anyone from it.\""), .direct("How was the defendant with patients?", "\"Great. {D.He} was calm, kind, and careful with the medications, and patients asked for {D.him} by name.\""), .direct("Did the defendant seem to know nursing?", "\"Yes. {DF} knew the procedures and answered questions the way an experienced nurse would on the floor.\""), .direct("Were you surprised by the audit?", "\"Shocked. I would have trusted {D.him} with my own family, and I still cannot believe what I heard.\""), .cross("Did you check the defendant's license?", "\"No. That was the administrator's job, and I never saw the paperwork that came in with the hire.\""), .cross("Did {D} ever say where {D} went to school?", "\"A school in another state, I think. I never looked it up, and I did not think to ask.\""), .cross("Did the defendant ever ask you to cover for something?", "\"No. {DF} never asked me for anything odd, and I never saw {DF} hide a thing at work.\""), .cross("Do you know if the defendant actually paid someone?", "\"Only what {D.he} told me. I never saw money change hands, and I never saw a receipt.\""), .cross("Are you friends with the defendant?", "\"We were friendly at work, and I am telling you what I knew from those shifts, nothing more.\"")],
        theory: ("{D} made a false diploma and used it to get hired.", "{D} trusted a placement company with the paperwork."),
        allocution: "\"I should have checked everything. I am sorry.\"",
        truths: ("The invoice and the placement company are traced to a mailbox registered to {DL}.", "The placement company is a real business that has been sued by several other job seekers."),
        defendant: [.direct("Did you make the diploma?", "\"No. I paid a placement company to handle my credentials, and they sent me the files.\""), .direct("Who made it?", "\"The company I paid. They said they had a way to verify my training and send everything to employers.\""), .direct("The file came from your computer, didn't it?", "\"They sent it to me to forward. I saved it and emailed it to the clinic.\""), .direct("You have no school record, do you?", "\"They said it would come through. I did not know the school had no record of me.\""), .direct("Did you think you were licensed?", "\"I thought the company was processing it. I did not know the license number was fake.\""), .direct("What do you want the clinic to know?", "\"I apologize. I thought the paperwork was handled, and I did my job as well as I could.\""), .cross("You sent the diploma and the license form to the clinic, didn't you?", "\"Yes. I forwarded what I was given.\""), .cross("The state board has no license under that number, does it?", "\"So the board says. I did not know.\""), .cross("The school never enrolled you, did it?", "\"So the school says. I did not check.\""), .cross("The diploma was made on your computer, wasn't it?", "\"The metadata says so. I forwarded it, and I did not make it.\""), .cross("You worked as a floor nurse for a year, didn't you?", "\"Yes, and I did the work well.\"")],
        openings: ("{D} emailed a nursing diploma and a licensing form to a medical clinic and was hired as a floor nurse. A year-end audit found the state board had no license under that number, the school had no student by that name, and the diploma PDF was made on {D}'s home computer.", "{D} paid a placement company to handle the paperwork and forwarded what it sent. A nurse who did the work well and trusted the wrong company is a victim of a fraud, not its author."),
        closings: ("A diploma made on {D}'s computer, a license that does not exist, a school that never enrolled {D}, and a year as a floor nurse. {D} presented those papers.", "A placement company, files sent to forward, and a year of good work. The State must prove {D} knew the credentials were fake."),
        timeline: [(-365, "{DL} emails the diploma and form."), (-360, "{DL} is hired."), (0, "The credential audit begins."), (7, "The board and school reply.")],
        identified: "A credential audit and file metadata.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let gymLockerWalletV1 = SmallCases.make(
        key: "story.gymLockerWallet",
        category: .property,
        headlines: ["Wallet Vanishes From Bag at Youth Swim Meet", "Parent's Trunk Search Turns Up Missing Wallet"],
        law: "misdLarceny",
        spec: "Stole a wallet and $210 in cash belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "During a youth swim meet at a community pool on {DATE}, {V}'s gym bag was left on a bleacher while {V.he} timed a race. The wallet inside, with $210, disappeared. A pool camera showed {D} lifting a bag off that bleacher. Deputies later found the wallet in the trunk of {D}'s car. {DL} says the bag looked like {D.his} own and {D.he} set the wallet aside to return it.",
        state: [E(.video, 3, "Pool Camera", "{D} picks up a blue gym bag from the third bleacher row, looks inside, and carries it out."), E(.physical, 3, "Wallet in Trunk", "{V}'s wallet, with the cash gone, was in a duffel in {D}'s trunk.", .search)],
        defense: [E(.statement, 1, "Same Bag", "{DL} says the bags were the same model and color.")],
        role: "Meet timer",
        exam: [.direct("Where was your bag during the meet?", "\"On the third bleacher row, while I timed a race. I left it there with my wallet inside.\""), .direct("What was in it?", "\"A wallet with $210. I had cash from a weekend trip, and I kept it in the wallet.\""), .direct("Was there a similar bag nearby?", "\"A few blue bags, yes. Many parents use the same kind, and they were all on the bleachers.\""), .direct("What does the pool camera show?", "\"It shows {D} picking up a blue gym bag from the third bleacher row, looking inside, and carrying it out.\""), .direct("Where was the wallet found?", "\"In the trunk of {D.his} car, in a duffel. The cash was gone.\""), .direct("Did {D} give it back?", "\"Not at the pool. {D.He} carried the bag out, and I did not see it again until deputies called.\""), .cross("Did the defendant take the wallet or the bag?", "\"The bag. {D.He} picked up a blue gym bag and looked inside, which is what the camera shows.\""), .cross("Could the defendant have mistaken the bag?", "\"It is possible. There were several blue bags, and they look alike.\""), .cross("Did you speak with the defendant?", "\"Later, at the station. {D.He} said it was a mistake and that {D.he} meant to return the wallet.\""), .cross("Was the cash ever found?", "\"No. The wallet was in the trunk with the cash gone.\""), .cross("Did the defendant take anything else?", "\"No. Nothing else was missing from my bag.\"")],
        theory: ("{D} took the wallet from a bag and left with the cash.", "A mistaken pickup of a look-alike bag."),
        allocution: "\"I should have turned it in. I am sorry.\"",
        truths: ("{DL} spent $60 at a snack stand with a twenty that matched the denominations of the missing cash.", "{DL}'s own blue bag, a match for the other, was found on the wrong bleacher with a name tag."),
        defendant: [.direct("Did you take the wallet?", "\"I took the wrong bag. It looked like my own, and I picked it up and left the pool.\""), .direct("Why was the wallet in your trunk?", "\"I meant to return it. I found it in the bag when I got home and put it aside to bring back.\""), .direct("Where is the cash?", "\"It was never there. I did not take cash, and the wallet was empty when I saw it.\""), .direct("Why did you not tell the staff?", "\"I did not get a chance. I realized the mistake at home, and I planned to bring it back the next day.\""), .direct("Why did you look inside the bag at the pool?", "\"I was checking for my goggles. The bag looked like mine, and I opened it quickly.\""), .direct("What do you want the owner to know?", "\"I apologize. I took the wrong bag by mistake, and I did not take your money.\""), .cross("You picked up a bag that was not yours, didn't you?", "\"Yes. It looked like mine, and I did not check.\""), .cross("You looked inside it, didn't you?", "\"Yes, at the pool. I was looking for my things.\""), .cross("The wallet was in your trunk, wasn't it?", "\"Yes, in a duffel. I had put it aside.\""), .cross("$210 was missing, wasn't it?", "\"So the owner says. I did not take it.\""), .cross("You never called the pool or the owner, did you?", "\"No. I wish I had. I waited too long.\"")],
        openings: ("During a youth swim meet, {V} left a gym bag on a bleacher while timing a race, and the wallet inside, with $210, disappeared. A pool camera showed {D} lifting a bag off that bleacher, and deputies later found the wallet in the trunk of {D}'s car.", "The bag looked like {D}'s own, and {D} set the wallet aside to return it. Taking the wrong bag is a mistake, not a theft."),
        closings: ("A bag lifted from the third bleacher row, a look inside, and a wallet in {D}'s trunk with the cash gone. {D} carried the bag out and kept it.", "A row of identical blue bags, a wrong pick, and a wallet put aside to return. The State must prove {D} meant to steal."),
        timeline: [(0, "9:15 a.m.: the bag is left on the bleacher."), (0, "9:50 a.m.: {D} lifts it."), (0, "11 a.m.: {V} reports the wallet missing."), (1, "Deputies search the trunk.")],
        identified: "A pool camera and a trunk search.",
        mood: .indifferent)

    static let campusThreatV1 = SmallCases.make(
        key: "story.campusThreat",
        category: .publicOrder,
        headlines: ["Threatening Note Slid Under Professor's Office Door", "Library Print Log Ties Note to Student ID"],
        law: "communicatingThreats",
        spec: "Willfully threatened to physically injure {V}, a professor, on {DATE}.",
        ages: 18...30,
        victim: true,
        summary: "On the morning of {DATE}, {V}, a professor, found a printed note under the office door reading, 'Fix my grade or I will be waiting at your car.' The paper came from the library printers. The print log tied the job to {D}'s student ID at 11 p.m. the night before. {DL} says {D.he} lent the card to a classmate.",
        state: [E(.document, 3, "Threat Note", "A printed note with a threat to wait at the professor's car."), E(.digital, 3, "Print Log", "The job printed at 11:04 p.m. on {D}'s student ID, from the third floor.")],
        defense: [E(.statement, 1, "Lent Card", "{DL} says a classmate borrowed the ID card for printing.")],
        role: "Professor",
        exam: [.direct("What did the note say?", "\"'Fix my grade or I will be waiting at your car.' It was printed and slid under my office door.\""), .direct("When did you find it?", "\"On the morning of the date in question, when I arrived. It was lying just inside the door.\""), .direct("Is {D} your student?", "\"Yes, and {D} got a failing grade. {D.He} had been unhappy with it.\""), .direct("Was the note signed?", "\"No. It had no name, no initials, and no date.\""), .direct("How did it get traced?", "\"The paper came from the library printers. The print log tied the job to {D.his} student ID at 11:04 p.m. the night before.\""), .direct("How did the note make you feel?", "\"Afraid. I walked to my car that night with campus police beside me, and I did not sleep well.\""), .cross("Did the defendant approach your car?", "\"No. No one approached my car. I was escorted.\""), .cross("Did the defendant threaten you in person?", "\"No. {D.He} filed an appeal and wrote an email, and both were polite.\""), .cross("Could someone else have used the defendant's ID?", "\"It is possible. I am not an expert on the print system.\""), .cross("Did the defendant deny it?", "\"Yes. {D.He} said {D.he} lent the card to a classmate.\""), .cross("Was {D} angry about the grade?", "\"Yes. {D.He} was upset and said so, but {D.he} followed the appeal process.\"")],
        theory: ("{D} printed a threat after failing a class.", "A classmate printed with a borrowed ID."),
        allocution: "\"I was angry. I am sorry.\"",
        truths: ("A library camera shows {DL} alone at the third-floor printers at 11 p.m.", "The library camera shows a different student using the printer at 11:04 p.m."),
        defendant: [.direct("Did you print the note?", "\"No. I did not print it, and I did not slip it under the professor's door.\""), .direct("Where was your ID?", "\"With a classmate. I lent my card to a friend from my study group that night.\""), .direct("You were angry about the grade, weren't you?", "\"Yes, but I filed an appeal. I followed the rules, and I did not threaten anyone.\""), .direct("Who borrowed it?", "\"A friend from my study group. I will give the name to anyone who asks.\""), .direct("Why did you lend the card?", "\"The friend needed to print a paper, and the library printers charge by student ID. I trusted the friend.\""), .direct("What do you want the professor to know?", "\"I am sorry you were frightened. I did not write that note, and I would never threaten you.\""), .cross("Your ID printed the note at 11:04 p.m., didn't it?", "\"Yes. My card was used, and I was not there.\""), .cross("You failed the class, didn't you?", "\"Yes. I was upset, and I appealed.\""), .cross("You cannot prove the friend used it, can you?", "\"The friend can tell you. I hope the friend will.\""), .cross("The note concerned your grade, didn't it?", "\"So the note says. I did not write it.\""), .cross("You had a motive to threaten the professor, didn't you?", "\"I had a grade I disagreed with. That is not the same.\"")],
        openings: ("On the morning after a late print job, {V}, a professor, found a note under the office door: 'Fix my grade or I will be waiting at your car.' The print log tied the job to {D}'s student ID at 11:04 p.m., and {D} had failed {V}'s class.", "{D} lent the student ID to a classmate and filed an appeal. An angry student who follows the rules did not write that note."),
        closings: ("A threat about a grade, a print job on {D}'s ID, and a failed class. The motive, the card, and the timing all point to {D}.", "A borrowed card, an appeal filed, and a note no one signed. The State must prove {D} was the one at the printer."),
        timeline: [(-3, "{DL} fails the final exam."), (-1, "11:04 p.m.: the note is printed."), (0, "Morning: the professor finds the note."), (1, "Campus police pull the print log.")],
        identified: "A library print log.",
        mood: .wantsConviction,
        impact: "I walk to my car with a colleague now.")

    static let golfCartDeathV1 = SmallCases.make(
        key: "story.golfCartDeath",
        category: .traffic,
        headlines: ["Passenger Dies as Golf Cart Hits Tree on Lake Road", "Party Guest Charged After Fatal Cart Crash"],
        law: "felonyDBV",
        threshold: 7,
        spec: "Unlawfully and unintentionally caused the death of {V} while driving a golf cart on a gravel road while impaired, on {DATE}.",
        ages: 24...60,
        victim: true,
        summary: "At about 12:30 a.m. on {DATE}, {D} drove a golf cart down a steep gravel road from a lake house party toward the dock, with {V} riding alongside. The cart left the road and struck a pine tree. {V} was thrown and died of a head injury. A blood draw at 2:15 a.m. put {DL} at 0.10. {DL} says {V} reached across and grabbed the wheel as a joke and that the road had washed out in a storm.",
        state: [E(.forensic, 3, "Blood Draw", "0.10 at 2:15 a.m., nearly two hours after the crash."), E(.document, 3, "Crash Reconstruction", "About 19 mph into the curve on a downhill grade; the cart's skid marks run straight to the tree."), E(.statement, 2, "Party Host", "{DL} drank steadily from 7 p.m. and took the cart keys without asking.")],
        defense: [E(.video, 2, "Porch Video", "A doorbell camera shows {V} jumping on the cart and gesturing toward the wheel."), E(.document, 1, "Road Washout", "A county report notes the gravel road washed out after the week's storm.")],
        role: "Highway Patrol reconstructionist",
        exam: [.direct("How fast was the cart?", "\"About nineteen miles an hour on a downhill curve, based on my reconstruction of the scene.\""), .direct("Why did the cart leave the road?", "\"A sober driver would have slowed. There were no brake marks until the tree, and the skid marks run straight to it.\""), .direct("Was the road damaged?", "\"There was some washout. The gravel had eroded in places, but it was not impassable.\""), .direct("What did the blood draw show?", "\"0.10 at 2:15 a.m., nearly two hours after the crash. It would have been higher at the time of the crash.\""), .direct("What happened to {V}?", "\"{V} was thrown from the cart and died of a head injury. {V} was not wearing any restraint.\""), .direct("What did the host say?", "\"That {D} drank steadily from 7 p.m. and took the cart keys without asking.\""), .cross("Could someone grabbing the wheel change that?", "\"It could, but I found no evidence of it. I found no scuff or mark that would show it.\""), .cross("Was the washout a factor?", "\"It could have been. Loose gravel can make a cart slide on a downhill curve.\""), .cross("Did {D} stay at the scene?", "\"Yes. {D.He} stayed, called for help, and tried to help {V}.\""), .cross("Was 19 mph fast for that cart?", "\"On a steep gravel curve, it is fast. On a flat road, it is slow.\""), .cross("Is there evidence {V} reached for the wheel?", "\"A guest says so. I did not find physical evidence, but I do not rule it out.\"")],
        defenseRole: "Guest on the porch",
        defenseExam: [.direct("Where were you that night?", "\"On the porch of the lake house, watching people head toward the dock.\""), .direct("What did you see?", "\"{V} jumped on the cart and reached toward the wheel, laughing. It was a joke, and {D} was laughing too.\""), .direct("Did you see the crash?", "\"No. It was around the bend. I heard a bang and then screams.\""), .direct("How did {V} and {D} act?", "\"Like close friends. They had been joking all night and were in a good mood.\""), .direct("How was the defendant acting?", "\"Normal. {D.He} was walking steadily and talking clearly.\""), .direct("What did you do after the bang?", "\"I ran down the hill with a flashlight. {D.He} was kneeling next to {V} and calling for help.\""), .cross("Did you see {V} grab the wheel?", "\"I saw {V} reach toward it. I did not see the grab.\""), .cross("How much did the defendant drink?", "\"I do not know. I saw {D.him} with a drink several times.\""), .cross("Did you see the keys taken?", "\"No. I do not know how {D.he} got the cart.\""), .cross("Were you drinking?", "\"A little. I was sober enough to know what I saw.\""), .cross("Are you friends with the defendant?", "\"We are friends. I am telling you what I saw, and I would say it about anyone.\"")],
        theory: ("{D} drank, drove a cart too fast down a gravel hill, and killed {V}.", "A prank at the wheel and a washed-out road."),
        allocution: "\"{V} was my close friend. I wish I had never taken the keys.\"",
        truths: ("A guest told investigators {DL} said, \"Watch this,\" before gunning the cart.", "A second guest says {V} was laughing and reaching for the wheel when the cart swerved."),
        defendant: [.direct("How much did you drink?", "\"Three drinks across the night. I felt fine, and I did not feel impaired when I got on the cart.\""), .direct("What happened on the hill?", "\"{V} grabbed the wheel as a joke, and the cart pulled right. I tried to correct it, and we slid.\""), .direct("What about the washout?", "\"The road had washed out in places. The gravel was loose, and the curve was steeper than it looks.\""), .direct("Your blood alcohol was 0.10, wasn't it?", "\"I cannot argue with the test. I did not feel it, but I accept what it says.\""), .direct("You took the keys, didn't you?", "\"I thought I was fine, and I did not think about asking the host. I wish I had asked.\""), .direct("What do you want {V}'s family to know?", "\"I am devastated. {V} was my friend, and I would give anything to change that night.\""), .cross("You drove a golf cart after drinking, didn't you?", "\"Yes. I should not have, and I know that now, and I feel awful about it.\""), .cross("You were going 19 mph down a steep curve, weren't you?", "\"So the reconstruction says. I did not feel it was fast, but it was too fast for that curve.\""), .cross("You never braked before the tree, did you?", "\"No. It happened so fast that I did not have time to think of the brake.\""), .cross("{V} died because of that crash, didn't {V.he}?", "\"Yes. I will carry that for the rest of my life, whatever happens here.\""), .cross("You took the keys without asking, didn't you?", "\"Yes. I thought it was fine, and I should have asked the host first.\"")],
        openings: ("At about 12:30 a.m., {D} drove a golf cart down a steep gravel road from a lake house party toward the dock with {V} riding alongside. The cart left the road and struck a pine tree, {V} was thrown and died, and a blood draw put {D} at 0.10.", "{V} reached across and grabbed the wheel as a joke, and the road had washed out. A cart that pulled hard on loose gravel is a tragedy, not a crime."),
        closings: ("19 miles an hour into a downhill curve, no braking, a 0.10 two hours later, and keys taken without asking. {D} drove, and {V} died.", "A joke at the wheel, a washed-out road, and a loose-gravel curve. The State must prove {D} was impaired and reckless, not that the road failed."),
        timeline: [(0, "7 p.m.: the party begins."), (0, "12:30 a.m.: the cart leaves for the dock."), (0, "12:35 a.m.: the cart hits the tree."), (0, "2:15 a.m.: {D}'s blood is drawn.")],
        identified: "{DL} was behind the wheel when responders arrived.",
        aggravating: ["The defendant's driving placed others at serious risk"],
        mitigating: ["The defendant has accepted responsibility", "The defendant has a support system in the community"],
        mood: .sympathetic,
        impact: "{V} left for a weekend at the lake and never came home.",
        doctrines: ["burdenOfProof", "expertTestimony", "lesserIncluded"])

