        exam: [.direct("What did you see in the hall?", "\"{D} walked up and {V} backed away. Then there was a punch, and {V} fell against the wall.\""), .direct("What did the gym security video show?", "\"It shows {DL} walking up to {V} in the hall, {V} stepping back, {DL} swinging, and {V} falling against the wall.\""), .direct("How was {V} hurt?", "\"A cheek broken against a cinder block wall. {V} needed a plate and a week off work.\""), .direct("What had led to this?", "\"A technical foul called on {D.his} child during a fifth-grade game. {D.He} followed {V} into the hallway.\""), .direct("What did the scorekeeper say?", "\"That {D.he} yelled at {V} for most of the fourth quarter. I heard some of it too.\""), .direct("How old is {V}?", "\"Nineteen. {V} was a young referee working youth games, and {V} was alone in the hall.\""), .cross("Did {V} put an arm out?", "\"It looks like it on the tape. {V} raised a forearm as {DL} came close.\""), .cross("Was it a shove?", "\"Hard to say. It was fast, and the angle does not show where the forearm landed.\""), .cross("Did {V} touch {D}?", "\"I cannot tell. The camera is above and to the side.\""), .cross("Did the defendant stay at the scene?", "\"Yes. {D.He} stayed, helped {V}, and said {D.he} was sorry.\""), .cross("Was the defendant threatening before the punch?", "\"Loud, but I did not hear a threat.\"")],
        defenseRole: "Parent in the stands",
        defenseExam: [.direct("Where were you during the game?", "\"In the stands, watching my child's team. I had a good view of the hall door.\""), .direct("What did you see?", "\"{V} put a forearm up as {D} walked close. It looked like a warning gesture.\""), .direct("Did {V} touch {D}?", "\"I could not tell. They were close, and the forearm was between them. Their arms were close, but I could not see where the forearm landed.\""), .direct("How did the defendant behave during the game?", "\"Loudly, like many parents. {D.He} shouted about the call and was not alone. Plenty of parents were loud, but {D.he} stayed on {V} longer than most.\""), .direct("What did the defendant do after the punch?", "\"Stood there stunned, then knelt down and asked if {V} was all right.\""), .direct("How did {V} behave toward parents?", "\"Calm for a young referee. I thought {V} handled a hard game well. I thought {V} handled a hard game well for someone so young.\""), .cross("Did you see the defendant swing?", "\"Yes. I saw the swing, and I saw {V} fall.\""), .cross("Did you hear what was said?", "\"Only shouting. I could not make out words.\""), .cross("Was {V} aggressive?", "\"No. {V} stepped back and raised a forearm.\""), .cross("Would you have swung?", "\"No. I would never hit a teenager.\""), .cross("Are you friends with the defendant?", "\"We are parents on the same team. I would tell the same story about anyone.\"")],
        theory: ("{D} chased a teenage referee and broke a bone.", "A referee's forearm came first and {D} reacted."),
        allocution: "\"I lost my temper over a youth game. I am sorry.\"",
        truths: ("{DL} had texted another parent, \"That ref is going to learn today.\"", "The sound on the tape picks up {V} saying, \"Back off or I will move you,\" before the forearm rises."),
        defendant: [.direct("Why did you follow {V}?", "\"To ask about the call. My child was upset about the technical foul, and I wanted an explanation.\""), .direct("Did {V} touch you?", "\"A forearm came up at my chest. I felt it before I swung.\""), .direct("You swung first, didn't you?", "\"I reacted. I swung at the forearm, and I hit {V}'s face. It happened in less than a second, and I have replayed it a hundred times since.\""), .direct("You broke a teenager's face, didn't you?", "\"I did not mean that. I was reacting, and I would never intend that kind of injury. I never wanted anyone hurt, least of all a young person doing a hard job.\""), .direct("How did you feel after?", "\"Sick. I knelt beside {V} and apologized, and I called for help.\""), .direct("What do you want {V} to know?", "\"I feel awful about it. I was wrong to follow you, and I am sorry for your pain.\""), .cross("You yelled at {V} for most of the fourth quarter, didn't you?", "\"I was loud, yes. I was upset about the call. I know that was out of line for a parent at a youth game.\""), .cross("You followed {V} into a hallway, didn't you?", "\"Yes. I wanted to talk, and I should have let it go.\""), .cross("The video shows you swing at {V}, doesn't it?", "\"Yes. It shows a swing.\""), .cross("{V} backed away before you swung, didn't {V.he}?", "\"Yes. {V} stepped back and raised a forearm. The camera shows what it shows, and I will not argue with it.\""), .cross("{V} needed surgery because of your punch, didn't {V.he}?", "\"Yes. I am so sorry. I think about that every single day, and I will keep paying for it.\"")],
        openings: ("After a fifth-grade basketball game, {D} followed {V}, a 19-year-old referee, into the hallway over a technical foul called on {D}'s child. Gym security video shows {V} step back and raise a forearm, and {D} swing, breaking {V}'s cheekbone.", "{V} put a forearm up first, and {D} reacted. A parent who swung in reflex did not mean to break a teenager's face."),
        closings: ("A parent who yelled all quarter, followed a teenage referee into a hall, and swung. {V}'s cheekbone was broken and needed surgery.", "A forearm at {D}'s chest, a reflex swing, and no intent to maim. The State must prove {D} struck {V} on purpose."),
        timeline: [(0, "7:30 p.m.: the technical foul is called."), (0, "8:15 p.m.: the game ends."), (0, "8:20 p.m.: the hallway fight."), (1, "{V} has surgery on the cheekbone.")],
        identified: "Gym security video.",
        aggravating: ["The victim was a youth sports official"],
        mood: .wantsConviction,
        doctrines: ["selfDefense"])

    static let scriptPadPrintV1 = SmallCases.make(
        key: "story.scriptPadPrint",
        category: .whiteCollar,
        headlines: ["Stolen Prescription Pad Used at Four Pharmacies", "Pharmacist's Call-Back Leads to Arrest"],
        law: "forgery",
        threshold: 7,
        spec: "Forged prescriptions of {V}, a physician, with intent to defraud, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A pad of prescription blanks went missing from an exam room at {V}'s clinic in the spring. On {DATE}, four scripts for painkillers with {V}'s forged signature turned up at pharmacies in two towns. One pharmacist called the clinic and the scripts were reported fake. {D} was seen on pharmacy video. {DL} says a friend asked {D.him} to pick up the medicine.",
        state: [E(.physical, 3, "Pad Stub Count", "Four blanks from the missing pad matched the serial numbers on the four scripts."), E(.video, 3, "Pharmacy Video", "{D} drops a script at the counter at two stores and signs for the pickup."), E(.document, 2, "Call-Back Record", "A pharmacist's note: the physician says no such order.")],
        defense: [E(.statement, 1, "Friend's Request", "{DL} says a friend asked {D.him} to pick up the prescriptions."), E(.document, 1, "Text Messages", "A text thread asks {DL} to \"grab my meds.\"")],
        role: "Pharmacist",
        exam: [.direct("What made you call the clinic?", "\"The signature was too neat and the pad number was wrong. It did not match the prescriptions I usually see from that doctor.\""), .direct("Who dropped off the scripts?", "\"{D}, on two of the scripts, at my store. {D.He} handed over a script and waited for the pickup.\""), .direct("What did the pharmacy video show?", "\"It shows {DL} dropping a script at the counter at two stores and signing for the pickup.\""), .direct("What did the clinic tell you?", "\"The physician said there was no such order. I wrote that on my call-back record.\""), .direct("What medicines were on the scripts?", "\"Painkillers. All four were for strong opioid pain medication, in quantities that were high.\""), .direct("How did you feel about the scripts?", "\"Uneasy. They looked good at first glance, and then small details did not match.\""), .cross("Did {D} write them?", "\"I cannot say. I did not see anyone write them. I only saw {DL} hand them over.\""), .cross("Did the defendant seem nervous?", "\"A little. Many customers are nervous at a pharmacy counter.\""), .cross("Did the defendant say who sent the scripts?", "\"Yes. {DL} said a friend asked {DL} to pick up the medicine.\""), .cross("Did the defendant try to leave when you called the clinic?", "\"No. {D.He} waited at the counter until I told {D.him} there was a problem.\""), .cross("Were the pills handed over?", "\"No. I held the order and the clinic was called.\"")],
        theory: ("{D} presented forged scripts from a stolen pad.", "A favor for a friend who handed over the paper."),
        allocution: "\"I should never have helped. I am sorry.\"",
        truths: ("A used practice sheet of {V}'s signature was found in {DL}'s car.", "The friend who sent the texts has a prior forgery charge and moved away the week after."),
        defendant: [.direct("Did you forge a signature?", "\"No. I did not write any script or sign any doctor's name. I never saw the pad.\""), .direct("Who gave you the scripts?", "\"My friend. My friend asked me to pick up the medicine because of a back problem.\""), .direct("You signed for the pills, didn't you?", "\"For my friend. I signed because the pharmacy asked me to, and I thought it was normal.\""), .direct("You went to two towns, didn't you?", "\"That is where my friend sent me. I did not ask why.\""), .direct("Did you know the scripts were fake?", "\"No. I would never have taken them if I knew. I thought they were real prescriptions.\""), .direct("What do you want the clinic to know?", "\"I feel awful about it. I trusted a friend, and I did not know the scripts were stolen.\""), .cross("You carried four scripts to two stores, didn't you?", "\"Yes. I carried what my friend gave me.\""), .cross("You signed for the pickups, didn't you?", "\"Yes. I signed my name.\""), .cross("The scripts carried the doctor's forged signature, didn't they?", "\"So the pharmacist says. I did not know.\""), .cross("You cannot produce your friend, can you?", "\"I can give a name. I do not know where the friend is now.\""), .cross("You never asked why a friend needed two towns, did you?", "\"No. I should have.\"")],
        openings: ("A pad of prescription blanks went missing from an exam room at {V}'s clinic, and four scripts for painkillers with {V}'s forged signature turned up at pharmacies in two towns. {D} was seen on pharmacy video dropping scripts and signing for pickups.", "A friend asked {D} to pick up the medicine, and {D} did as asked. A person who carries a script for someone else is not the one who forged it."),
        closings: ("Four blanks from the missing pad, four forged scripts, and {D} on video at two stores signing for pickups. {D} handled every one.", "A friend's request, a signature given at the counter, and a forger no one has found. The State must prove {D} knew the scripts were fake."),
        timeline: [(-30, "The pad goes missing from an exam room."), (0, "Morning: the first script is filled."), (0, "Afternoon: the pharmacist calls the clinic."), (3, "{D} is identified from the video.")],
        identified: "Pharmacy video and a call-back to the clinic.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let weddingGiftBoxV1 = SmallCases.make(
        key: "story.weddingGiftBox",
        category: .property,
        headlines: ["Retirement Party Envelope Box Disappears From Church Hall", "Hall Camera Shows Helper Carrying Cash Box"],
        law: "misdLarceny",
        spec: "Stole gift cards and cash valued at $1,200 belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A cardboard box holding $1,200 in cash and gift cards for {V}'s retirement party vanished from the church fellowship hall on {DATE}. A hall camera showed {D}, a volunteer, carrying a similar box out the side door. Two days later a bank deposit in {D}'s account matched part of the cash. {DL} says the box was an empty decoration {D.he} was throwing away.",
        state: [E(.video, 3, "Hall Camera", "{D} lifts a box from the gift table and walks out the side door at 8:40 p.m."), E(.digital, 2, "Bank Deposit", "A cash deposit of $620 in {DL}'s account two days later.")],
        defense: [E(.statement, 1, "Empty Decoration", "{DL} says the box was an empty centerpiece for the trash.")],
        role: "Event coordinator",
        exam: [.direct("What was on the gift table?", "\"A box of cards, cash, and gift cards for {V}'s retirement party, about $1,200 in all.\""), .direct("Who left with a box?", "\"{D}, by the side door. A volunteer lifted a box from the table and walked out at 8:40 p.m.\""), .direct("Were there other boxes?", "\"Two decorative ones. They were plain cardboard boxes used as centerpieces.\""), .direct("What did the hall camera show?", "\"It shows {DL} lifting a box from the gift table and walking out the side door at 8:40 p.m.\""), .direct("What did the bank deposit show?", "\"A cash deposit of $620 in {D.his} account two days later. It matched part of what was missing.\""), .direct("What happened when you noticed?", "\"I looked at the table at the end of the night and the box was gone. I called the pastor.\""), .cross("Did anyone see {D} open it?", "\"No. No one saw {DL} open the box or take anything from it.\""), .cross("Could the box the defendant carried have been a decoration?", "\"It could have been. It looked similar, and the camera cannot tell.\""), .cross("Did the defendant deny taking the cash?", "\"Yes. {D.He} said it was an empty decoration and that {D.he} was throwing it away.\""), .cross("Where is the dumpster?", "\"Outside the side door. Volunteers carry trash out that way.\""), .cross("Has the defendant volunteered before?", "\"Yes, for years. I have never had a problem with {D.him}.\"")],
        theory: ("{D} walked out with a retirement gift box.", "A volunteer throwing out an empty decoration."),
        allocution: "\"I should not have done it. I am sorry.\"",
        truths: ("The empty centerpiece was still in the supply closet and the missing box was not.", "A second volunteer says the empty centerpiece went to the dumpster at 8:40 p.m. and {DL} carried it."),
        defendant: [.direct("What was in the box?", "\"Nothing. It was trash. An empty decoration box that I was throwing away.\""), .direct("Why the side door?", "\"The dumpster is out there. That is the way volunteers go when they take out trash.\""), .direct("What about the deposit?", "\"It was from yard sale money. I had sold furniture and tools that weekend.\""), .direct("Why did you not tell anyone?", "\"It was trash. I did not think it needed an announcement.\""), .direct("How did you feel when you learned?", "\"Horrified. I volunteered for the church for years, and I would never take a gift meant for a retiree.\""), .direct("What do you want {V} to know?", "\"I am sorry the gifts were lost. I did not take them, and I hope they are found.\""), .cross("You carried a box out the side door at 8:40, didn't you?", "\"Yes. It was an empty box, and I was throwing it away.\""), .cross("A deposit of $620 hit your account two days later, didn't it?", "\"Yes. From my yard sale. I can show the sales.\""), .cross("The box with the gifts was never found, was it?", "\"No. I wish it had been.\""), .cross("You are the one the camera shows, aren't you?", "\"Yes. I did not think anything of it.\""), .cross("Two decorative boxes were on the table, weren't they?", "\"So I understood. I took one.\"")],
        openings: ("A cardboard box holding $1,200 in cash and gift cards for {V}'s retirement party vanished from a church fellowship hall. A camera showed {D}, a volunteer, carrying a box out the side door, and two days later a bank deposit in {D}'s account matched part of the cash.", "The box {D} carried was an empty decoration headed for the dumpster. The deposit was yard sale money, and {D} has volunteered here for years."),
        closings: ("A box lifted from the gift table, a side door at 8:40, and a deposit of $620 two days later. The timing leaves little room for coincidence.", "An empty decoration, a dumpster outside the side door, and a yard sale. The State must prove {D} took the gift box and not a decoration."),
        timeline: [(0, "6 p.m.: the party begins."), (0, "8:40 p.m.: {D} carries a box out the side door."), (0, "9 p.m.: the gift table is empty."), (2, "The deposit is made.")],
        identified: "A hall camera and a bank deposit.",
        mood: .indifferent)

    static let neighborDogShotV1 = SmallCases.make(
        key: "story.neighborDogShot",
        category: .publicOrder,
        headlines: ["Retriever Hit by Steel Shot, Vet Says", "Backyard Camera Catches Neighbor With Slingshot"],
        law: "animalCruelty",
        spec: "Maliciously killed or injured an animal belonging to {V} with a slingshot, on {DATE}.",
        ages: 25...65,
        victim: true,
        summary: "{V}'s retriever limped home on {DATE} with two steel ball bearings lodged in a hind leg and needed surgery. A yard camera caught {D} at the fence line with a slingshot. {V} and {D} had argued over the dog digging under the fence. {DL} says {D.he} was shooting at a raccoon on {D.his} fence.",
        state: [E(.document, 3, "Vet Records", "X-rays show two steel ball bearings lodged in the leg and a $2,300 surgery bill."), E(.video, 2, "Yard Camera", "{D} draws a slingshot toward the dog by the fence at dusk."), E(.physical, 2, "Ball Bearings", "A coffee can of matching bearings in {DL}'s shed.", .search)],
        defense: [E(.statement, 1, "Raccoon", "{DL} says a raccoon was on the fence and {D.he} fired at it.")],
        role: "Veterinarian",
        exam: [.direct("What did you find when you examined {V}'s dog?", "\"Two steel balls in a hind leg and torn muscle. The X-rays show two ball bearings lodged deep in the leg.\""), .direct("Could it have been an accident?", "\"A ball that size is a deliberate shot from a sling. It is not something that arrives by accident.\""), .direct("Could a ricochet cause it?", "\"Possible. A ball can bounce off a hard surface and hit an animal, though the damage suggests a direct hit.\""), .direct("What did the surgery involve?", "\"We removed both ball bearings and repaired torn muscle. The bill was $2,300.\""), .direct("Will the dog recover?", "\"Mostly, with a limp. The leg will not be quite the same.\""), .direct("What did the yard camera show?", "\"It shows {D} drawing a slingshot toward the dog by the fence at dusk. I saw the clip.\""), .cross("Can you say who fired it?", "\"No. I treat animals, and I cannot identify a shooter.\""), .cross("Were bearings like these found elsewhere?", "\"A coffee can of matching bearings was in {D.his} shed. I know that only from the report.\""), .cross("Could the dog have been hit by someone else?", "\"Possible. Slingshots are common, and the ball is a common size.\""), .cross("Did the dog dig under the fence?", "\"The owner said so. I do not know.\""), .cross("Was the dog in pain?", "\"Yes, a great deal. It limped in and was very sore.\"")],
        theory: ("{D} shot a neighbor's dog out of spite.", "A shot meant for a raccoon went astray."),
        allocution: "\"I was careless with a slingshot. I am sorry.\"",
        truths: ("{DL} texted a friend, \"That dog will not dig again.\"", "{V}'s camera shows a raccoon on the fence at the same moment as {D}'s shot."),
        defendant: [.direct("Did you shoot the dog?", "\"No. I did not shoot the dog. I was shooting at a raccoon on my fence.\""), .direct("What were you aiming at?", "\"A raccoon. It was on the top rail at dusk, and I was trying to scare it off.\""), .direct("The dog was beside the fence, wasn't it?", "\"It ran in front of me just as I let go. I did not see it until too late.\""), .direct("You argued with {V}, didn't you?", "\"About digging. The dog dug under my fence, and I complained.\""), .direct("Why did you have a coffee can of bearings?", "\"For the slingshot. I use it to scare off raccoons and crows. I have never shot an animal on purpose.\""), .direct("What do you want {V} to know?", "\"I am sorry the dog was hurt. I did not mean it, and I will help pay for the surgery.\""), .cross("The camera shows you drawing the slingshot toward the dog, doesn't it?", "\"It shows me drawing toward the fence. The dog was beside it.\""), .cross("You and {V} had argued about the dog digging, hadn't you?", "\"Yes. It was a minor argument, and I was not angry enough to hurt a dog.\""), .cross("You keep steel bearings in your shed, don't you?", "\"Yes, for the slingshot. I have used them for years.\""), .cross("A steel ball is a harsh thing to shoot at a raccoon, isn't it?", "\"It works. I never meant to hit an animal I could see.\""), .cross("The dog needed $2,300 surgery because of your shot, didn't it?", "\"So the vet says. I truly am sorry.\"")],
        openings: ("{V}'s retriever limped home with two steel ball bearings lodged in a hind leg and needed surgery. A yard camera caught {D} at the fence line drawing a slingshot toward the dog, and a coffee can of matching bearings was in {D}'s shed.", "{D} was shooting at a raccoon on the fence, and the dog ran in front. An argument about digging does not make a slingshot shot deliberate."),
        closings: ("Two steel balls in a dog's leg, a slingshot drawn toward the dog on camera, and a can of matching bearings in {D}'s shed. The dog dug, and {D} shot.", "A raccoon on the fence, a dog that ran into the line, and an old argument about digging. The State must prove {D} aimed at the dog."),
        timeline: [(-14, "{V} and {D} argue over the digging."), (0, "Dusk: the yard camera records the shot."), (0, "Evening: the dog limps home."), (1, "The vet finds the steel balls.")],
        identified: "A yard camera and veterinary X-rays.",
        mood: .divided,
        genders: ["D": .male])

    static let crossingGuardCrashV1 = SmallCases.make(
        key: "story.crossingGuardCrash",
        category: .traffic,
        headlines: ["Delivery Truck Strikes Crossing Guard at School Dismissal", "Fleet GPS Puts Box Truck at Crosswalk"],
        law: "hitAndRun",
        threshold: 7,
        spec: "Failed to stop at the scene of a crash the defendant knew or reasonably should have known resulted in the death of {V}, near a school crosswalk, on {DATE}.",
        ages: 24...62,
        victim: true,
        summary: "At 3:10 p.m. on {DATE}, in steady rain, {V}, 66, a crossing guard at an elementary school, stepped into the marked crosswalk with a stop sign raised. A white box truck turning right struck {V} and kept going. {V} died at the hospital. A parent's dashcam recorded the truck's rear and part of a company logo. Fleet GPS placed {D}'s delivery truck at the corner at 3:10. {DL} says the truck's right mirror was fogged, {D.he} felt a bump like a pothole, and kept to {D.his} route.",
        state: [E(.video, 3, "Parent Dashcam", "A white box truck with a partial logo turns right through the crosswalk without slowing."), E(.digital, 3, "Fleet GPS", "{D}'s truck is stamped at the corner at 3:10 p.m. and speeds up after the turn."), E(.physical, 2, "Truck Damage", "A dent in the right front bumper and orange fabric fibers on the grille.", .search)],
        defense: [E(.document, 2, "Weather and Mirror", "Rain was heavy and a repair ticket noted a cracked right mirror."), E(.document, 1, "Delivery Schedule", "A tight schedule with a dispatcher's text: keep moving.")],
        role: "State Highway Patrol trooper",
        exam: [.direct("What did the dashcam show?", "\"A white truck turning right through a crosswalk with a guard in it, without slowing, in steady rain.\""), .direct("Who was struck?", "\"{V}, 66, a crossing guard at an elementary school, who had stepped into the crosswalk with a stop sign raised.\""), .direct("How did you find the truck?", "\"The logo and the fleet GPS pointed to {D}'s route. The GPS stamps {D.his} truck at the corner at 3:10 p.m.\""), .direct("What did you find on the truck?", "\"A dent in the right front bumper and orange fabric fibers on the grille. They match the guard's vest.\""), .direct("Was it raining hard?", "\"It was. Rain affected visibility and the road, and I note that in my report.\""), .direct("What happened after the turn?", "\"The truck sped up and kept going. {V} died at the hospital.\""), .cross("Was the mirror cracked?", "\"There was a ticket for it. A cracked mirror can reduce visibility on that side.\""), .cross("Could the driver see {V}?", "\"It is possible the driver did not see {V} through the rain and the mirror.\""), .cross("Did {D} call in a crash?", "\"No. The company has no record of a call from {D.him}.\""), .cross("Did the defendant cooperate?", "\"Yes. {D.He} met with us and said {D.he} felt only a bump.\""), .cross("Was the guard wearing bright clothing?", "\"An orange vest, which is what left the fibers.\"")],
        defenseRole: "Dispatcher",
        defenseExam: [.direct("What is your role?", "\"I am a dispatcher at the delivery company. I schedule routes and track trucks.\""), .direct("What was {D}'s schedule that day?", "\"Twenty stops in four hours. It was a tight schedule, and {D} was behind.\""), .direct("Did the defendant call in a crash?", "\"No. {D.He} never called in anything unusual, either by radio or by phone, and I would have written it down.\""), .direct("How did the defendant sound on the radio?", "\"Normal. {D.He} sounded rushed and a little annoyed about the rain, but nothing out of the ordinary came over the radio.\""), .direct("How is the defendant as a driver?", "\"Safe, with a clean record. I have dispatched {D.him} for years and never had a complaint. I would say the same about any driver I dispatch every day.\""), .direct("What did you learn later?", "\"That a crossing guard had been struck. I was sick about it and told the sheriff what I knew.\""), .cross("Did you tell the defendant to hurry?", "\"I scheduled twenty stops. I did not tell {D.him} to hurry in words.\""), .cross("Did you hear anything about a bump?", "\"No. {D.He} said nothing about it that day.\""), .cross("Could {D} have been on a phone?", "\"I do not know. I do not monitor that.\""), .cross("Did the truck's mirror get fixed?", "\"I do not know. A ticket was filed for it.\""), .cross("Are you friendly with the defendant?", "\"We talk daily. I am telling you what I know.\"")],
        theory: ("{D} hit a crossing guard and drove on.", "A driver in the rain who felt a bump and did not know."),
        allocution: "\"I wish I had stopped. I will carry this.\"",
        truths: ("{DL}'s phone shows a search for \"hit a person and left what happens\" at 3:40 p.m.", "The truck's in-cab camera shows {DL} checking the mirror and shaking {D.his} head, with no sign of seeing a person."),
        defendant: [.direct("Did you feel the impact?", "\"A bump, like a pothole. I felt something under the right front wheel and thought it was the road.\""), .direct("Why did you keep going?", "\"I thought I hit the curb. It was raining hard, and I did not see anyone.\""), .direct("You turned right through a crosswalk, didn't you?", "\"The rain was heavy. The wipers were slapping, and I did not see a person or a sign.\""), .direct("What about the grille fibers?", "\"I never saw anyone. I do not know how the fibers got there.\""), .direct("When did you learn what happened?", "\"Later that day, when the sheriff called. I was devastated, and I could not stop shaking.\""), .direct("What do you want {V}'s family to know?", "\"I am so sorry. If I had known, I would have stopped and stayed with {V}.\""), .cross("Your right front bumper has a dent, doesn't it?", "\"So the trooper says. I thought it was a curb.\""), .cross("You sped up after the turn, didn't you?", "\"I was behind schedule. I did not mean to flee.\""), .cross("A crossing guard in an orange vest was in front of you, wasn't there?", "\"I did not see {V}. The rain was heavy.\""), .cross("Your mirror was cracked, wasn't it?", "\"Yes. There was a ticket. I should have fixed it.\""), .cross("You searched online for what happens when you hit a person and leave, didn't you?", "\"I did, later that afternoon. I had a bad feeling after I heard about it, and I did not realize at the time that I had hit anyone.\"")],
        openings: ("In steady rain at 3:10 p.m., {V}, 66, a crossing guard, stepped into a marked crosswalk with a stop sign raised. A white box truck turning right struck {V} and kept going, and fleet GPS placed {D}'s delivery truck at the corner at that moment.", "{D} felt a bump like a pothole in heavy rain and never saw a person. A driver who did not know cannot be guilty of fleeing."),
        closings: ("A truck stamped at the corner at 3:10, a dent in the bumper, orange fibers on the grille, and no stop. {V} died because the truck kept going.", "Heavy rain, a cracked mirror, and a driver who felt only a bump. The State must prove {D} knew {D.he} hit a person and left."),
        timeline: [(0, "3:10 p.m.: the truck strikes {V}."), (0, "3:50 p.m.: {V} dies at the hospital."), (0, "Evening: GPS data is pulled."), (1, "Troopers inspect the truck.")],
        identified: "A parent's dashcam and fleet GPS.",
        aggravating: ["The victim was crossing at a marked school crosswalk"],
