        threshold: 2,
        spec: "Unlawfully and with malice killed {V} by stabbing {V.him} with a knife.",
        ages: 24...40,
        victim: true,
        summary: "At 11:30 p.m. on {DATE}, at a public boat ramp after a fish fry, {D} and {V} argued over $300 {V} said was owed. Guests agree {V} followed {D} to a truck, shouting. They disagree on whether {V} swung a tire iron first. {V} was stabbed twice and died before the ambulance reached the ramp. {D} drove off, tossed a hunting knife into the river, and called a friend. {DL} turned {D.himself} in the next morning.",
        state: [E(.forensic, 2, "Autopsy", "Two stab wounds to the chest; one nicked the heart."), E(.physical, 2, "Hunting Knife", "A hunting knife dragged out of the river, matching the wound width.", .search), E(.statement, 1, "Boat Ramp Guests", "Three guests saw {D} leave after the stabbing and heard {D.him} say, \"Call someone.\"")],
        defense: [E(.physical, 1, "Tire Iron", "A tire iron lay by {V}'s feet with {V}'s fingerprints.")],
        role: "Sheriff's detective",
        exam: [.direct("Describe what you found when you arrived at the ramp.", "\"{V} was on the ground near a truck with two stab wounds to the chest. An ambulance had been called, but {V} died before it reached the ramp.\""), .direct("What did the guests tell you about the argument?", "\"Three guests said {V} and {D} argued over $300 that {V} said was owed. They said {V} followed {DL} to a truck, shouting.\""), .direct("What else was at the scene?", "\"A tire iron lay near {V}'s feet, and a lab found {V}'s fingerprints on it.\""), .direct("What did the autopsy show?", "\"Two stab wounds to the chest, one of which nicked the heart. Either could have been fatal.\""), .direct("What happened to {D}?", "\"{DL} drove away, threw a hunting knife into the river, and called a friend. The next morning {DL} turned {D.himself} in at the sheriff's office.\""), .direct("Where is the knife now?", "\"Divers recovered it from the river two days later. It matched the wounds.\""), .cross("Did the guests agree on who swung first?", "\"They did not. Some said {V} had the tire iron up, and others said it was on the ground.\""), .cross("Whose fingerprints were on the tire iron?", "\"{V}'s. Only {V}'s were identified.\""), .cross("Did the defendant resist arrest or try to flee after turning {D.himself} in?", "\"No. {D.He} came in voluntarily and answered my questions.\""), .cross("Did the defendant say anything to the guests as {D.he} left?", "\"Three guests heard {DL} say to call someone. That's in their statements.\""), .cross("Had anyone seen {V} threaten the defendant before?", "\"A couple of guests said {V} had been cursing and had a bar in hand earlier.\"")],
        defenseRole: "Guest at the fish fry",
        defenseExam: [.direct("How do you know {D} and {V}?", "\"I'm a friend of both. We all go to the same church and the fish fry is a yearly event.\""), .direct("What did you see at the ramp?", "\"{V} cursing at {D} and waving a tire iron. {V} said something about hitting {DF} with it.\""), .direct("How was {V} acting?", "\"Angry and loud. {V} had been drinking and said {DF} owed money.\""), .direct("Did you see the defendant do anything to provoke {V}?", "\"No. {DF} was walking away and I saw {V} follow.\""), .direct("What did you do?", "\"I stepped back and then heard someone yell. I didn't see the stabbing itself.\""), .direct("What did you see afterward?", "\"{V} on the ground and {DF} backing away. {DF} said to call someone, and then {DF} drove off.\""), .cross("Did you see the tire iron in {V}'s hand when the stabbing happened?", "\"I saw {V} holding it earlier. I didn't see the exact moment.\""), .cross("Did you see the defendant use a knife?", "\"Only afterward. I didn't see the blade.\""), .cross("How far were you from the truck?", "\"About thirty feet. It was dark by the ramp.\""), .cross("Are you close to the defendant?", "\"Yes, we're friends, and I know that matters.\""), .cross("Did anyone say {V} swung the tire iron?", "\"Some did. I can't say I saw it.\"")],
        theory: ("{D} stabbed {V} and hid the knife.", "{D} defended against a swinging tire iron and panicked."),
        allocution: "\"I never wanted anyone dead. I am sorry.\"",
        truths: ("{DL} had told a friend {D.he} would \"settle it tonight\" before the fish fry.", "{V} had said at the party, \"I will hit you with that bar.\""),
        defendant: [.direct("Tell us about the fish fry and the argument.", "\"It was a church fish fry at a public boat ramp. {V} and I got into an argument about $300 that {V} said I owed.\""), .direct("What happened when you walked to your truck?", "\"{V} followed me, shouting. I turned around and {V} had a tire iron and was swinging it.\""), .direct("What did you do?", "\"I had my hunting knife on my belt. I pulled it and stabbed {V} twice. It happened in seconds.\""), .direct("Why did you leave?", "\"I panicked. I got in my truck and drove away, and I told a friend what had happened.\""), .direct("Why did you throw the knife in the river?", "\"I was scared and I didn't know what to do. I'm not proud of it.\""), .direct("Why did you turn yourself in?", "\"It was the right thing. I couldn't live with myself otherwise.\""), .cross("You told a friend you'd 'settle it tonight' before the fish fry. What did you mean?", "\"I meant the money. I wanted to talk it out and get it done.\""), .cross("Two stab wounds to the chest. Is that self-defense?", "\"It was fast, and I was afraid. I didn't aim.\""), .cross("You left a dying person on the ground. Why not stay and call 911?", "\"I told someone to call. I panicked, and I should have stayed.\""), .cross("Why throw away the knife if it was self-defense?", "\"Because I was scared. I thought I'd be blamed.\""), .cross("{V}'s fingerprints are on a tire iron. But no one saw {V} swing it?", "\"Some guests did. It was dark and things happened quickly.\"")],
        openings: ("At a boat ramp after a church fish fry, an argument over $300 ended with {V} stabbed twice in the chest. {D} drove off, threw the knife into the river, and turned {D.himself} in the next day.", "{V} followed {D} to a truck with a tire iron in hand and swung it. The defense will show a frightened person who pulled a knife in seconds, panicked afterward, and then did the right thing."),
        closings: ("Two wounds, one to the heart, a knife thrown into a river, and a debt as the reason. Whatever happened at the ramp, {D} hid the weapon and left {V} to die.", "A tire iron with {V}'s fingerprints, a debt, a chase, and seconds to react. {D} panicked, then came forward on {D.his} own. The State has to prove {D} wasn't defending {D.himself}, and it cannot."),
        timeline: [(0, "9 p.m.: the fish fry begins."), (0, "11:30 p.m.: the argument turns to a fight."), (0, "11:35 p.m.: {V} is stabbed."), (1, "{D} turns {D.himself} in.")],
        identified: "Guests at the fish fry and a recovered knife.",
        notDone: ["The tire iron was not tested for {D}'s prints beyond the surface."],
        mood: .divided,
        doctrines: ["selfDefense", "imperfectSelfDefense"],
        genders: ["D": .male, "V": .male])

    static let washedChecksV1 = SmallCases.make(
        key: "story.washedChecks",
        category: .whiteCollar,
        headlines: ["Altered Checks Deposited Through Phone App", "Bank Fraud Unit Traces Deposits to One Phone"],
        law: "forgery",
        threshold: 7,
        spec: "Forged checks of {V} and others with intent to defraud, totaling $14,000, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Between a church's mail box and the bank, six checks were altered with the payee changed and the amounts raised. On {DATE}, the bank's fraud unit saw the checks deposited through a phone app tied to {D}'s device. {V}, a church treasurer, reported the original checks never arrived. {DL} says a friend asked to use {D.his} phone for deposits.",
        state: [E(.digital, 3, "App Deposit Records", "Six checks were deposited through a device registered to {D}, within four days."), E(.document, 3, "Altered Checks", "Images show ink smears and a different pen in the payee line."), E(.video, 2, "ATM Camera", "{D} withdraws cash at the credit union kiosk the day after the deposits.")],
        defense: [E(.statement, 1, "Borrowed Phone", "{DL} says a friend used the deposit app on {D.his} phone."), E(.document, 1, "Friend's Texts", "Texts ask to \"use your phone for a minute.\"")],
        role: "Bank fraud investigator",
        exam: [.direct("Describe your job as a bank fraud investigator for the jury.", "\"I investigate suspicious deposits and altered checks. When a deposit looks wrong, I trace the device, the account, and the images of the checks.\""), .direct("How did this case come to you?", "\"A church treasurer reported that six checks mailed to vendors never arrived. Then our system flagged six deposits through a phone app, all in four days.\""), .direct("What did the check images show?", "\"The payee lines had ink smears and a different pen from the signature, and the amounts had been raised. Someone had washed the original ink and rewritten it.\""), .direct("Which device made the deposits?", "\"A phone registered to {D}. The app logged the phone's ID and a login from {D.his} account each time.\""), .direct("What did you learn about the cash?", "\"The day after the last deposit, {DL} withdrew cash from the credit union kiosk. The ATM camera shows {DL} at the machine.\""), .direct("What did you do next?", "\"We froze the account, notified the church treasurer {V}, and reported the matter to the sheriff's office.\""), .cross("Does the device ID prove who was holding the phone?", "\"No. It proves whose phone it was, not who was using it.\""), .cross("Is it possible someone else used {D}'s phone?", "\"It's possible. The app logs the device, not the person, and I can't say who pressed the buttons.\""), .cross("Was the defendant on camera making any of the deposits?", "\"No. The deposits were mobile, so there's no camera for them.\""), .cross("How much did the defendant withdraw?", "\"About $600 on one day. The rest remained in the account until we froze it.\""), .cross("Did you see any text between the defendant and a friend?", "\"Yes, in the file the sheriff's office gave us. A friend asked to use the phone for a minute.\"")],
        theory: ("{D} altered checks and cashed them out.", "A friend used {D}'s phone for deposits."),
        allocution: "\"I should never have let it happen. I am sorry.\"",
        truths: ("A bottle of solvent and a stack of blank checks were in {DL}'s trunk.", "The friend who borrowed the phone was caught the next month with another person's checks."),
        defendant: [.direct("Describe your phone for the jury.", "\"I have a basic phone with a banking app. I don't keep a lock on it all the time, and friends borrow it sometimes.\""), .direct("Did you alter any checks?", "\"No. I've never washed or rewritten a check, and I wouldn't know how.\""), .direct("Who used your phone to make those deposits?", "\"A friend who asked for it for a minute. The friend said it was to check a balance.\""), .direct("What did you do when the bank froze your account?", "\"I was shocked. I called the bank and told them a friend had used my phone, and I gave the friend's name.\""), .direct("Why did you withdraw cash that day?", "\"For rent. I'd had the cash planned for days.\""), .direct("Have you talked to the friend since?", "\"No. The friend stopped answering my calls and I haven't seen {D.him} since.\""), .cross("The deposits went into your account. Who benefited?", "\"I did, though I didn't know where the money came from. I thought it was a friend paying me back.\""), .cross("You withdrew cash the next day. Isn't that suspicious?", "\"It was rent. I'd needed that amount for a week.\""), .cross("You can't produce the friend. Why should the jury believe you?", "\"I'd rather not be the only one blamed. I'm telling the truth, and the texts show a friend asking for my phone.\""), .cross("Six checks in four days. Didn't you notice them?", "\"I looked at my balance and saw it was higher. I didn't look closely.\""), .cross("You didn't report the friend. Why not?", "\"I thought it was a misunderstanding. I didn't think it would be a crime.\"")],
        openings: ("Six checks that never reached their vendors were washed, rewritten, and deposited through a phone app tied to {D}. The day after the last deposit, {D} withdrew cash at the credit union.", "A phone does not write a check, and jurors will see that. A friend borrowed {D}'s phone, the friend vanished, and the bank has only a device number and a cash withdrawal for rent."),
        closings: ("Six altered checks, deposited by one phone in four days, and {D} at the kiosk the day after. The money went into {D}'s account, and {D} spent it.", "A phone number is not a pen. A friend asked for the phone, the texts show it, and the friend disappeared. The State has proved whose phone it was, not who used it."),
        timeline: [(-7, "Checks leave the church's mailbox."), (0, "First deposit through the app."), (4, "Last deposit."), (5, "The bank freezes the account.")],
        identified: "Bank app records and an ATM camera.",
        mood: .wantsConviction,
        doctrines: ["mistakeOfFact"],
        genders: ["D": .male])

    static let kayakDockTheftV1 = SmallCases.make(
        key: "story.kayakDockTheft",
        category: .property,
        headlines: ["Kayak Missing From Cabin Rack, Then Listed Online", "Serial Number Match Ends Marketplace Sale"],
        law: "misdLarceny",
        spec: "Stole a kayak valued at $650 belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}'s red kayak, worth $650, was lifted off a rental-cabin rack overnight on {DATE}. Three days later a red kayak was listed online from {D}'s account. {V} spotted the hull number in the photo and told a deputy. {DL} says {D.he} found the kayak drifting loose at the lake edge and was trying to sell it for the owner.",
        state: [E(.digital, 3, "Online Listing", "A kayak photo with {V}'s hull number, posted from {D}'s account for $400."), E(.physical, 2, "Hull Number", "The serial plate on the recovered kayak matches {V}'s purchase receipt.")],
        defense: [E(.statement, 1, "Found Drifting", "{DL} says the kayak floated up on the shore of the cove.")],
        role: "Cabin owner",
        exam: [.direct("Tell us about the cabin and where the kayak was kept.", "\"I own a rental cabin on a lake. Guests can use the kayaks I keep on a rack beside the cabin, and I tie each one to the rack with a strap.\""), .direct("What kind of kayak was it?", "\"A red sit-on-top, bought new for $650. It had a hull number on a plate near the stern.\""), .direct("When did you notice it was missing?", "\"On the morning of the day in question, I found the rack empty and one strap cut. The kayak was gone from the dock area.\""), .direct("How did you find it again?", "\"A friend sent me a link three days later. The listing showed a red kayak for $400 with the hull number visible in the photo.\""), .direct("How did you confirm it was yours?", "\"I compared the hull number with my purchase receipt. They matched, and a deputy checked the serial plate on the recovered kayak.\""), .direct("What did you do then?", "\"I called the sheriff's office and sent the listing. A deputy contacted the person who'd posted it.\""), .cross("Could the kayak have floated off from the rack?", "\"It was tied with a strap, so it's unlikely. I can't say the strap held up in the wind.\""), .cross("Did {D} contact you before you contacted the sheriff?", "\"No. I never heard from {D}.\""), .cross("Was the strap frayed?", "\"One strap was cut and another was worn. I replaced the straps after that.\""), .cross("Did anyone see the defendant take the kayak?", "\"No. I have no witness who saw it taken.\""), .cross("How far is the cove from the rack?", "\"About a quarter mile along the shore. A loose kayak could drift that far in a night.\"")],
        theory: ("{D} took a kayak and sold it online.", "A found kayak listed for the owner."),
        allocution: "\"I should have called the owner. I am sorry.\"",
        truths: ("A cut tie-down strap was in {DL}'s truck.", "The rack's straps were frayed and the kayak slid off in the night wind."),
        defendant: [.direct("Tell us how you came upon the kayak.", "\"I was fishing at the edge of the cove and saw a red kayak floating against the shore. It looked abandoned, with no paddle and no one around.\""), .direct("What did you do with it?", "\"I pulled it onto the bank and put it in my truck. I thought about the owner and figured I could help find them.\""), .direct("Why did you list it online?", "\"I thought I'd post it so the owner would see it. I put a price of $400 as a guess and said it was found.\""), .direct("Did you notice the hull number?", "\"I saw a number on the plate but didn't think about it. I left it visible in the photo so the owner could identify it.\""), .direct("What did you do when the deputy called?", "\"I told the deputy the truth and offered to return the kayak. I've never taken anything that wasn't mine.\""), .direct("Why did you take it home instead of calling someone?", "\"It was late and I wasn't sure who to call. I meant to look for an owner in the morning.\""), .cross("You listed it for $400. Isn't that a sale price?", "\"It was a guess. I wasn't trying to profit, and I'd have given it back.\""), .cross("You never called the sheriff's office or the cabin. Why not?", "\"I didn't know whose it was. I thought the listing was the best way to find the owner.\""), .cross("A cut strap was in your truck. How do you explain that?", "\"I carry straps and cutters for fishing. It's a common thing to have.\""), .cross("The kayak was on a cabin rack three days earlier. How did it get to the cove?", "\"I don't know. I assumed it drifted.\""), .cross("Isn't a kayak with a hull number obviously someone's property?", "\"Yes. That's why I posted the number. I wanted the owner to see it.\"")],
        openings: ("{V}'s red kayak, worth $650, was lifted off a cabin rack overnight. Three days later a kayak with the same hull number was listed online for $400 from {D}'s account.", "{D} found a loose kayak at the edge of a cove and tried to find the owner by posting it. The defense will show a listing that displayed the hull number openly and a straps rack that was already failing."),
        closings: ("A kayak on a rack by the cabin, a cut strap, and a listing with the hull number three days later. The kayak was {V}'s and it was for sale at a price from {D}'s account.", "A kayak drifted into a cove, and {D} posted it with the hull number in plain view so the owner could find it. No one saw a theft, and the rack's straps were already frayed."),
        timeline: [(0, "Night: the kayak leaves the rack."), (1, "{V} reports it missing."), (3, "The listing appears."), (4, "A deputy contacts {D}.")],
        identified: "An online listing and a hull number.",
        mood: .indifferent)

    static let fairgroundRiotV1 = SmallCases.make(
        key: "story.fairgroundRiot",
        category: .publicOrder,
        headlines: ["Speedway Infield Brawl Draws Thirty and Injures Concession Worker", "Phone Video Shows Cooler Thrown Into Crowd"],
        law: "riot",
        threshold: 6,
        spec: "Participated in a public disturbance involving an assemblage of three or more persons, resulting in injury and property damage, on {DATE}.",
        ages: 18...40,
        victim: false,
        summary: "A dispute over seating at a county speedway on {DATE} became a brawl of about thirty people in the infield. A concession stand was knocked over and a worker's wrist was broken. A fan's phone video shows {D} throwing a cooler and shouting to others. {DL} says {D.he} was trying to shield friends and the cooler was a reflex.",
        state: [E(.video, 3, "Fan Phone Video", "{D} hurls a cooler toward the stand and shouts \"Get them!\""), E(.document, 2, "Injury and Damage Report", "A broken wrist and $1,100 in stand damage."), E(.statement, 1, "Track Security", "{D} was identified from the video as the one in a blue jersey.")],
        defense: [E(.statement, 2, "Shielding Friends", "{DL} says {D.he} put an arm around a friend and the cooler slipped.")],
        role: "Speedway security chief",
        exam: [.direct("Tell us about your job at the speedway.", "\"I'm the security chief at the county speedway. I supervise the guards, handle incident reports, and review video after any disturbance.\""), .direct("How did the brawl begin?", "\"A dispute over seating in the infield at about eight. It started as shouting between a few groups and grew to about thirty people by 8:30.\""), .direct("What damage and injuries resulted?", "\"A concession stand was knocked over, causing about $1,100 in damage, and a worker's wrist was broken. A few fans had cuts and bruises.\""), .direct("What does the fan's phone video show about {D}?", "\"{D}, in a blue jersey, hurls a cooler toward the stand and shouts something to others. The cooler lands near the stand and the crowd surges.\""), .direct("How did you identify the defendant?", "\"From the video and the blue jersey. Our guards later found {D.him} outside the gate and confirmed the ID.\""), .direct("Did the defendant shout anything?", "\"On the video, {DL} shouts what sounds like 'Get them!' It's hard to hear over the noise.\""), .cross("Did you see the defendant touch anyone?", "\"No. I was at the other side of the infield. I only know what the video shows.\""), .cross("Is the audio on the video clear?", "\"Not completely. There's a lot of shouting, and some words are lost.\""), .cross("How many people threw things?", "\"Several. The video shows at least four or five people throwing items.\""), .cross("Was the worker's wrist injured by the cooler?", "\"The injury report doesn't say. The worker told us someone shoved a stand panel.\""), .cross("Did the defendant try to leave the scene?", "\"{D.He} moved away after the cooler. We found {D.him} outside about twenty minutes later.\"")],
        defenseRole: "Friend of {DL}",
        defenseExam: [.direct("How do you know {D}?", "\"I'm a friend. We went to the speedway together with a few other people.\""), .direct("What was the defendant doing when the argument started?", "\"Standing near me. {D} said something like 'Let's go,' and tried to move us away.\""), .direct("What did you see the defendant do during the fight?", "\"Pull friends back from the crowd. {DF} had an arm around one friend and was saying to stop.\""), .direct("What happened with the cooler?", "\"It was in {DF}'s hand and it slipped when {DF} grabbed someone. It flew out into the crowd.\""), .direct("Did you hear the defendant shout?", "\"Yes. {D.He} was shouting to stop. I couldn't hear every word, but it wasn't a call to fight.\""), .direct("What happened afterward?", "\"We got separated, and I found {D.him} outside the gate about twenty minutes later.\""), .cross("Did you see the defendant throw the cooler?", "\"I saw it leave {D.his} hands. I can't say if it was thrown or dropped.\""), .cross("Are you close to {D}?", "\"Yes. We've been friends a long time.\""), .cross("Did you see the stand knocked over?", "\"Not the moment. I was looking at the crowd near us.\""), .cross("Did the defendant tell you to get anyone?", "\"Not that I heard.\""), .cross("Was the defendant part of the original argument?", "\"No. {D.He} wasn't involved in the seating dispute.\"")],
        theory: ("{D} threw a cooler and urged others on.", "A friend shielding others in a melee."),
        allocution: "\"I got swept up. I am sorry.\"",
        truths: ("{DL} texted afterward, \"We showed them,\" and posted the video.", "The video's audio shows {DL} yelling \"Stop, everybody stop,\" before the cooler."),
        defendant: [.direct("Walk us through what happened at the speedway.", "\"A seating argument started near us and got heated. Some of my friends were in the middle, and I tried to pull them back.\""), .direct("What were you shouting?", "\"'Stop, everybody stop.' I was trying to calm people down, and that's what the audio shows before the cooler.\""), .direct("How did the cooler leave your hands?", "\"I put my arm around a friend to shield {D.him} and the cooler slipped. It was heavy and I was holding it in one hand.\""), .direct("Where did you go after?", "\"I tried to find my friends in the crowd. I was worried about them.\""), .direct("Did you post anything afterward?", "\"I posted the video and said we'd showed them. I regret that. That was a foolish thing to write.\""), .direct("Do you know the worker who was hurt?", "\"No. I'm sorry for what happened. I'd pay for the stand if I could.\""), .cross("The video shows you yelling 'Get them!' Isn't that a call to others?", "\"I said stop. If I said anything else, it was lost in the noise.\""), .cross("You threw the cooler toward a stand. Isn't that deliberate?", "\"It slipped when I grabbed my friend. I didn't aim at anything.\""), .cross("After the brawl you texted that you 'showed them.' What did you mean?", "\"It was a boast, not a plan. I shouldn't have written it.\""), .cross("You stayed in the crowd. Why not leave?", "\"I wanted to find my friends. I was scared for them.\""), .cross("A worker's wrist was broken. Don't you share responsibility?", "\"I'm sorry for it. I didn't mean for it to happen, and I didn't touch the worker.\"")],
        openings: ("A seating argument at a county speedway grew into a brawl of thirty people. A concession stand was knocked over, a worker's wrist was broken, and a fan's video shows {D} hurling a cooler.", "{D} was trying to pull friends out of a melee, shouted for everyone to stop, and the cooler slipped from {D.his} hands. The defense will show a reflex in a crowd, not a plan to hurt anyone."),
        closings: ("A video of {D} hurling a cooler toward the stand, a shout to others, a broken wrist, and $1,100 in damage. A message afterward said, 'We showed them.'", "A crowded infield, a heavy cooler, a friend to shield, and a shout to stop on the audio. A slip in a melee is not a call to riot, and the State cannot prove otherwise."),
        timeline: [(0, "8 p.m.: the seating argument."), (0, "8:30 p.m.: the brawl spreads."), (0, "8:40 p.m.: the stand is knocked over."), (1, "Security identifies {D} from the video.")],
        identified: "A fan's phone video.",
        mood: .indifferent,
        genders: ["D": .male])

    static let unmarkedCarV1 = SmallCases.make(
        key: "story.unmarkedCar",
        category: .traffic,
        headlines: ["Driver Alone at Night Ran From Unmarked Truck, Called 911", "Lit Fire Station Where Chase Ended"],
        law: "fleeing",
