        spec: "Willfully interfered with {V}'s communication with a 911 operator, on {DATE}.",
        ages: 19...55,
        victim: true,
        summary: "On {DATE}, {V} called 911 from an apartment hallway after an argument with {D}, a former partner. The dispatcher heard {V} give an address, a shout of \"Give it back,\" and a crash. A neighbor's doorbell camera shows {D} slapping the phone out of {V}'s hand. {DL} says {V} dropped the phone while they tussled over car keys.",
        state: [E(.digital, 3, "911 Recording", "{V} says the address and then, \"Give it back,\" followed by a crash and a dropped line."), E(.video, 2, "Doorbell Video", "{D}'s hand swipes across and the phone clatters on the floor.")],
        defense: [E(.statement, 1, "Tussle Over Keys", "{DL} says both were grabbing for car keys and the phone fell.")],
        role: "911 dispatcher",
        exam: [.direct("Tell us what you do as a 911 dispatcher.", "\"I answer emergency calls, ask where the caller is, and send deputies, medics, or firefighters. Every call is recorded.\""), .direct("What did {V} say at the start of the call?", "\"{V} gave an address in an apartment building and said {V.he} needed deputies. {V} sounded scared and was speaking quickly.\""), .direct("What did you hear next?", "\"{V} shouted 'Give it back,' and then there was a crash and the line went dead.\""), .direct("What did you do?", "\"I tried to call back and sent deputies to the address. They arrived about nine minutes later.\""), .direct("Was there another voice on the call?", "\"A male voice in the background. I couldn't make out words.\""), .direct("How long was the line dead?", "\"About thirty seconds before it reconnected. I heard some sounds and then the call ended.\""), .cross("Could the phone have simply fallen?", "\"It could have. A crash on a hard floor is consistent with a dropped phone.\""), .cross("Did you hear anyone say they would hurt {V}?", "\"No. I heard shouting but not a threat.\""), .cross("Did you hear what the male voice said?", "\"Not clearly. I heard something like 'give me that' or 'stop.'\""), .cross("Did {V} say who was there?", "\"No. {V} gave the address and said {V.he} needed help.\""), .cross("How many seconds did the shout last?", "\"A few. It's hard to say with the noise.\"")],
