    static let oldMillRoadV1 = SmallCases.make(
        key: "story.oldMillRoad",
        category: .traffic,
        headlines: ["Pickup Runs Stop Sign at Crossroads, Kills Nurse", "Brush-Hidden Sign and Blood Test Split Trial"],
        law: "felonyDBV",
        threshold: 10,
        spec: "While impaired, unlawfully and unintentionally caused the death of {V} in a collision at a rural crossroads.",
        ages: 24...41,
        victim: true,
        summary: "At about dusk on {DATE}, {D}'s pickup passed a stop sign at a rural crossroads and struck the side of {V}'s car. {V}, 34, a nurse on the way home from a twelve-hour shift, died at the scene. {D}, a line cook, had left a bar after a long afternoon. A hospital blood draw about two hours after the crash and a State lab draw about four hours after it disagree about how impaired {DL} was at the time. {DL} says low sun and overgrown brush hid the stop sign.",
        state: [E(.forensic, 3, "Hospital Blood Test", "0.11 at the hospital two hours after the crash."), E(.document, 3, "Crash Reconstruction", "The pickup entered the crossroads at 48 mph with no braking before impact."), E(.statement, 2, "Bar Tab", "Six beers and a shot on {DL}'s card between 2 and 5 p.m."), E(.statement, 2, "Eyewitness", "A farmer saw the pickup roll through the sign without slowing.")],
        defense: [E(.document, 2, "Overgrown Sign", "Photos show brush covering half the stop sign from the pickup's lane."), E(.forensic, 2, "State Lab Test", "0.07 at the State lab four hours after the crash.")],
        role: "Highway Patrol reconstructionist",
        exam: [.direct("What can you tell us about your role and what you reconstructed?", "\"I'm a Highway Patrol crash reconstructionist. I examine physical evidence at a scene and calculate speeds, angles, and times.\""), .direct("What happened at the crossroads?", "\"A pickup passed a stop sign and struck the driver's side of {V}'s car. {V}, a nurse driving home from a long shift, died at the scene.\""), .direct("How fast was the pickup?", "\"About 48 miles an hour, with no braking before impact. There were no skid marks.\""), .direct("Could {D} have seen the stop sign?", "\"Partly. Brush covered about half of it, but the right side was visible.\""), .direct("What did the blood tests show?", "\"0.11 at the hospital about two hours after the crash, and 0.07 at the State lab about four hours after.\""), .direct("What did a witness see?", "\"A farmer in a field saw the pickup roll through the sign without slowing.\""), .cross("Was the sun low?", "\"Yes. It was low in the west and could have affected visibility.\""), .cross("Does a later test change the picture?", "\"Alcohol drops with time, so the earlier test is a better guide to the level at the crash.\""), .cross("Did the two tests disagree?", "\"They differ, but both are consistent with alcohol in the blood.\""), .cross("Did the county ever cut the brush?", "\"I don't know. I only know the brush was there.\""), .cross("Can you say the defendant was impaired at the moment of the crash?", "\"I can only say the speed and lack of braking are consistent with inattention, and I leave impairment to the lab.\"")],
        defenseRole: "County road maintenance supervisor",
        defenseExam: [.direct("What is your job with the county?", "\"I'm a road maintenance supervisor. I oversee crews that mow, trim brush, and replace signs.\""), .direct("What was the condition of that stop sign?", "\"Brush had grown across about half of it, from the pickup's lane. It had been that way for months.\""), .direct("Was a request made to cut it?", "\"A resident asked in the spring. The request was logged and not completed.\""), .direct("How should a sign like that be maintained?", "\"Brush should be trimmed back each season to keep signs visible. This one was overdue.\""), .direct("Did you inspect the site after the crash?", "\"Yes. I took photos and had the brush cut that week.\""), .direct("Would a driver coming from that lane have seen the sign?", "\"It would have been harder to see. The right half was visible, but the word 'stop' was partly hidden.\""), .cross("Was the sign still in place and legally valid?", "\"Yes. It was standing and met the legal requirements.\""), .cross("Would you expect a driver to see the cross-road even without the sign?", "\"A careful driver would see the intersection. I can't say what {D} saw.\""), .cross("Did anyone else have an accident at that crossing before?", "\"Not that I recall.\""), .cross("Was the brush a defense for a driver who had been drinking?", "\"I can't say. I only know the sign was partly hidden.\""), .cross("Did the sign's condition cause the crash?", "\"I can't say it did.\"")],
        theory: ("{D} drank for hours, drove through a stop sign, and killed {V}.", "A hidden sign, low sun, and a blood test that tells two stories."),
        allocution: "\"I took a life. I will never forgive myself.\"",
        truths: ("{DL} told a bartender, \"One more, I can handle it,\" at 4:45 p.m.", "The bar tab includes drinks for three other people and a receipt for food at 3:30."),
        defendant: [.direct("Describe your afternoon for the jury.", "\"I'm a line cook. I got off work and went to a bar with coworkers around two. We had some drinks and some food.\""), .direct("How much did you drink?", "\"Three beers, maybe four. The tab shows six, but some were for friends.\""), .direct("What do you remember about the crash?", "\"I was driving home with the sun in my eyes. I didn't see the sign, and I didn't see the car until it was too late.\""), .direct("Did you brake?", "\"No. I never saw the sign or the car, so I never hit the brakes.\""), .direct("What did you do after the crash?", "\"I got out and ran to the car. I stayed until help arrived and told the deputy everything I knew.\""), .direct("How are you coping with what happened?", "\"I can't stop thinking about it. {V} died, and I'm responsible for being there.\""), .cross("You told the bartender 'One more, I can handle it.' Did you say that?", "\"I may have said it. At the time I felt fine to drive.\""), .cross("Six beers and a shot over three hours. Isn't that a lot?", "\"It is. I didn't think it was affecting me.\""), .cross("Isn't it your duty to see a stop sign?", "\"It is. The brush covered it, but I should have been paying closer attention.\""), .cross("The hospital test said 0.11. Do you dispute that?", "\"I don't. I'm told it dropped by the State test.\""), .cross("You didn't brake at all. How can that be?", "\"The sun and the brush hid the sign, and I never saw it.\"")],
        openings: ("At dusk, {D}'s pickup passed a stop sign at 48 miles an hour with no braking and struck {V}'s car, killing a nurse who was driving home from a twelve-hour shift. {D} had been drinking since two that afternoon.", "Brush covered half the stop sign for months, the sun was low, and two blood tests disagree about how much alcohol {D} had. Jurors will hear a tragedy with more than one cause."),
        closings: ("Six beers and a shot, a pickup at 48 with no braking, a farmer who saw it roll through the sign, and a nurse who never made it home. {D} was impaired and {V} is dead.", "A sign no driver could fully read, a low sun, and two tests that do not agree. The State must prove {D} was impaired and that {D} saw what {D} could not."),
        timeline: [(0, "2 p.m.: {D} starts drinking at the bar."), (0, "6:40 p.m.: the crash at the crossroads."), (0, "8:40 p.m.: the hospital blood draw."), (0, "10:40 p.m.: the State lab blood draw.")],
        identified: "A witness and {DL} was at the scene.",
        aggravating: ["The defendant's driving placed others at serious risk"],
        mitigating: ["The defendant has accepted responsibility"],
        mood: .divided,
        impact: "{V} was the one who sat with dying patients. We could not be there for {V.him}.",
        doctrines: ["burdenOfProof", "expertTestimony"])

    static let unsecuredGunV1 = SmallCases.make(
        key: "story.unsecuredGun",
        category: .violent,
        headlines: ["Child Dies After Cousin Finds Loaded Pistol in Truck Console", "Fishing Trip Ends With Fatal Shot"],
        law: "invManslaughter",
        threshold: 4,
        spec: "Unintentionally killed {V}, age 6, by culpable negligence in leaving a loaded handgun unsecured where children were present.",
        ages: 28...42,
        victim: true,
        summary: "On {DATE}, during a family fishing trip at a pond, {D}'s seven-year-old and {V}, 6, climbed into {D}'s truck cab to play. In the unlocked center console they found {D}'s loaded pistol. The seven-year-old pulled the trigger once and {V} was struck and died. {DL} kept the pistol loaded for protection and left a lockbox on the truck bed, unused. {DL} says the truck was locked and the children had been warned to stay by the water.",
        state: [E(.statement, 2, "Child Interview", "The seven-year-old says, \"I knew where it was kept. The box was open.\""), E(.physical, 2, "Pistol and Lockbox", "A loaded pistol recovered from the console and an unused lockbox in the truck bed.", .search), E(.document, 2, "Purchase Records", "{D} bought the pistol and a lockbox six months earlier.")],
        defense: [E(.statement, 1, "Truck Locked", "{DL} says the truck was locked.")],
        role: "Sheriff's detective",
        exam: [.direct("Describe what you found when you arrived at the pond.", "\"A family fishing trip had turned into an emergency. {V}, six years old, had been shot and was being treated by medics. {D}'s child was nearby.\""), .direct("Where was the pistol?", "\"In the center console of {D.his} truck cab. It was a loaded semi-automatic with a round in the chamber.\""), .direct("Was it secured?", "\"A lockbox was in the truck bed, empty and unlocked. {D.He} had bought it six months earlier with the pistol.\""), .direct("What did the seven-year-old tell you?", "\"That {D.his} child knew where the pistol was kept and that the box was open. {D.his} child pulled the trigger once.\""), .direct("How did {D} respond?", "\"{D.He} was devastated and cooperated fully. {D.He} gave a statement and handed over the pistol.\""), .direct("What did you do with the pistol when you arrived at the pond?", "\"I photographed it where it lay, cleared it and logged it into evidence. I also photographed the center console and the lockbox in the garage.\""), .cross("Was the truck locked when you arrived?", "\"The doors were unlocked when we got there. {DL} said it had been locked earlier and that someone may have opened it.\""), .cross("Did the defendant cooperate with your investigation?", "\"Fully. {D.He} gave a statement, handed over the pistol, and answered every question I asked.\""), .cross("Were the children warned before the trip?", "\"Both families said the children were told to stay near the water. I can't verify exactly what was said.\""), .cross("Did anyone else have access to the truck?", "\"A relative opened a door to get a cooler. I wasn't able to confirm whether it was relocked.\""), .cross("Was the pistol in plain view from the seat?", "\"No. It was in the closed console. The child told me the child knew where it was kept.\"")],
        theory: ("{D} left a loaded pistol in a console where children played.", "A tragic accident after a locked truck and clear warnings."),
        allocution: "\"I will never forgive myself for not locking it away.\"",
        truths: ("{DL} had been told by a family member two weeks earlier to lock up the pistol and said, \"It is fine.\"", "The truck was locked when {DL} left; a relative opened the door to get a cooler and did not relock it."),
        defendant: [.direct("Tell the jury about the trip.", "\"We went to a pond with two families for the day. The children were told to stay by the water and the truck was locked.\""), .direct("Where did you keep your pistol?", "\"In the console, loaded, for protection. I'd bought a lockbox and meant to use it.\""), .direct("Why wasn't the pistol in the lockbox?", "\"I forgot. The box was in the truck bed and I hadn't put it in.\""), .direct("How did the children get into the truck?", "\"I don't know. I think someone opened the door to get a cooler and didn't relock it.\""), .direct("What did you do when you heard the shot?", "\"I ran to the truck. {V} was on the ground and I called for help while a relative did what we could.\""), .direct("How has this affected you?", "\"I can't forgive myself. I think about it every minute of every day.\""), .cross("You kept a loaded pistol in an unlocked console. Isn't that dangerous around children?", "\"Yes. I know it was, and I should have used the lockbox I bought.\""), .cross("A family member told you to lock it up two weeks before. What did you say?", "\"I said it was fine. I was wrong, and I have to live with that.\""), .cross("You say the truck was locked. Who else had a key?", "\"I did, and a relative who got a cooler. I locked it when we arrived.\""), .cross("The child said the lockbox was open. Why was it open?", "\"I had left it open in the truck bed. I meant to put the pistol in it and didn't.\""), .cross("You told the children to stay by the water. Did you check on them?", "\"Not constantly. We were fishing and I thought they were with the other adults.\"")],
        openings: ("A seven-year-old and a six-year-old climbed into {D}'s truck at a pond and found a loaded pistol in an unlocked console. One child fired it once and {V} died.", "{D} locked the truck and told the children to stay by the water, and a relative opened a door and did not relock it. Jurors will hear a tragedy, and decide whether it is a crime."),
        closings: ("A loaded pistol in a console, a lockbox sitting empty in the truck bed, and a child who knew where the gun was kept. {D} chose to keep it loaded and unsecured.", "A locked truck, clear warnings, and a door opened by someone else. A tragedy is not the same as criminal negligence, and the State has not shown one."),
        timeline: [(-180, "{D} buys the pistol and lockbox."), (0, "Morning: the family arrives at the pond."), (0, "Afternoon: the children climb into the truck."), (0, "Afternoon: the shot.")],
        identified: "A child interview and a pistol recovered from the truck.",
        mood: .sympathetic,
        impact: "{V} was six years old and loved fishing.")

    static let videoThreatExtortionV1 = SmallCases.make(
        key: "story.videoThreatExtortion",
        category: .whiteCollar,
        headlines: ["Coworker Demands $5,000 or Recording Goes to Boss", "Payment App Request Ties Threat to Employee"],
