        state: [E(.digital, 3, "Threat Messages", "\"Pay me five thousand by Friday or the owner gets the clip.\""), E(.digital, 3, "Payment Request", "A $5,000 app request sent from {D}'s account at 9:20 p.m."), E(.digital, 2, "Phone Copy", "A copy of the video was on {D}'s phone.", .search)],
        defense: [E(.statement, 2, "Just Venting", "{DL} says the message was meant to scare, not to collect."), E(.statement, 1, "Wrong Button", "{DL} says the request went out by accident.")],
        role: "Store manager",
        exam: [.direct("Tell us about your job and your relationship with {D}.", "\"I manage a retail store. {D} is an employee who works for me on weekends, and we've had a normal working relationship.\""), .direct("What happened at the staff meeting that week?", "\"I lost my temper with a customer earlier that day and swore at them in front of other employees. A few of them looked uncomfortable.\""), .direct("What message did you receive from the defendant?", "\"That {DL} had a video of me cursing at the customer and would send it to the owner unless I paid $5,000 by Friday.\""), .direct("What happened that night?", "\"At 9:20, a payment app request for $5,000 came from {D.his} account. I took a screenshot and called the sheriff's office.\""), .direct("How did you feel?", "\"Humiliated and afraid for my job. I'd never been threatened like that.\""), .direct("Did you ever see the video?", "\"No. {D.He} never sent it, and I don't know if it exists.\""), .cross("Did the defendant send the video to anyone?", "\"No. The owner never received it.\""), .cross("Did the defendant follow up with another request?", "\"The payment request came that night. Nothing after that.\""), .cross("Did you talk to the defendant before calling deputies?", "\"No. I was scared and I didn't want to confront {D.him}.\""), .cross("Had you lost your temper at work before?", "\"Once or twice. I'm not proud of it.\""), .cross("Did you pay anything?", "\"No. I declined the request and reported it.\"")],
        theory: ("{D} demanded money to keep a video quiet.", "A bad joke and a mistaken payment request."),
        allocution: "\"I should never have sent that message. I am sorry.\"",
        truths: ("{DL} was behind on rent and texted a friend, \"I am about to fix that with a clip.\"", "{DL}'s phone also holds an unsent apology draft to {V} written the same night."),
        defendant: [.direct("What can you tell us about your job at the store?", "\"I've worked weekends for about a year. I'm behind on rent and I've been stressed about money.\""), .direct("Did you record the manager?", "\"I took a short video of the manager cursing at a customer. I didn't plan to use it for anything.\""), .direct("Why did you send the message?", "\"It was a bad joke. I was frustrated and I wanted to scare the manager, not collect money.\""), .direct("What about the payment request?", "\"I hit the wrong button on my phone. I'd meant to cancel something and it went out.\""), .direct("What did you do when you realized?", "\"I panicked. I wrote an apology draft and never sent it.\""), .direct("Do you still have the video?", "\"I forgot it was on my phone. I'd never shown it to anyone.\""), .cross("You set a deadline of Friday. Isn't that a demand?", "\"I was making it sound real. I didn't intend to follow through.\""), .cross("You texted a friend that you were about to fix your rent with a clip. What did you mean?", "\"That was a foolish message to write. I didn't think of it as a real plan.\""), .cross("$5,000 is a lot for a joke. Why that amount?", "\"I picked a number. I wasn't thinking about what it would do.\""), .cross("You didn't say it was a joke until deputies called. Why not?", "\"I was afraid and I didn't know how.\""), .cross("You kept the video. Doesn't that show you meant to use it?", "\"I forgot it was there. I would have deleted it.\"")],
