        state: [E(.video, 3, "Booking Room Video", "{D} bears down on {V}'s shoulders from behind for five minutes while {V} slumps forward."), E(.forensic, 3, "Medical Examiner", "Cause of death: asphyxia due to neck and chest compression, with a heart condition contributing."), E(.document, 2, "Policy Manual", "Pressure on the neck of a restrained detainee is banned and was taught in annual training.")],
        defense: [E(.forensic, 2, "Toxicology", "Cocaine and an enlarged heart were found at autopsy."), E(.document, 1, "Booking Notes", "Notes record that {V} struck an officer earlier that evening.")],
